tangoRegister('n2', 'grammarExercises', {
  "1.0": [{"q":"{館内|かんない}の{施設|しせつ}をご{利用|りよう}になる（　　）、{会員証|かいいんしょう}をご{提示|ていじ}ください。","options":["{際|さい}は","{一方|いっぽう}で","ばかりか","につれて"],"answer":0,"vi":"Khi sử dụng các tiện ích trong tòa nhà, quý khách vui lòng xuất trình thẻ hội viên.","explain":"Vる＋際は dùng trong thông báo trang trọng nghĩa là 'khi…'. 一方で là đối lập, ばかりか là 'không những', につれて là thay đổi song song – đều không hợp."},{"q":"お{降|お}りの（　　）、お{忘|わす}れ{物|もの}のないようご{注意|ちゅうい}ください。","options":["おかげで","{際|さい}は","せいで","{末|すえ}に"],"answer":1,"vi":"Khi xuống xe, xin quý khách chú ý đừng để quên đồ.","explain":"Nの＋際は là cách nói trang trọng của thông báo công cộng. おかげで/せいで chỉ nguyên nhân, 末に là 'sau một quá trình dài' – không hợp."}],
  "1.1": [{"q":"{新|あたら}しい{工場|こうじょう}の{建設|けんせつ}（　　）、{地域|ちいき}の{住民|じゅうみん}に{説明会|せつめいかい}を{開|ひら}いた。","options":["に{限|かぎ}って","にかけては","に{際|さい}して","をはじめ"],"answer":2,"vi":"Nhân dịp xây dựng nhà máy mới, (công ty) đã tổ chức buổi giải thích cho cư dân địa phương.","explain":"に際して chỉ thời điểm đặc biệt, có chủ ý (việc xây dựng). に限って chỉ sự bất thường, にかけては nói về năng lực, をはじめ nêu ví dụ tiêu biểu."},{"q":"{海外|かいがい}へ{留学|りゅうがく}する（　　）、{両親|りょうしん}に{手紙|てがみ}を{書|か}いた。","options":["につれて","に{限|かぎ}らず","ばかりか","に{際|さい}して"],"answer":3,"vi":"Nhân dịp đi du học nước ngoài, tôi đã viết thư cho bố mẹ.","explain":"Du học là sự kiện đặc biệt, xảy ra một lần nên dùng に際して. につれて diễn tả thay đổi song song, に限らず/ばかりか nghĩa 'không chỉ'."}],
  "1.2": [{"q":"{新|あたら}しい{店|みせ}を{開|ひら}く（　　）、{多|おお}くの{方|かた}にご{協力|きょうりょく}いただきました。","options":["にあたって","につけて","ばかりか","かわりに"],"answer":0,"vi":"Khi mở cửa hàng mới, chúng tôi đã nhận được sự giúp đỡ của rất nhiều người.","explain":"にあたって dùng cho thời điểm bắt đầu một việc quan trọng, sắc thái tích cực. につけて là 'mỗi khi' kèm cảm xúc, ばかりか là 'không những', かわりに là 'thay vì'."},{"q":"{卒業|そつぎょう}{論文|ろんぶん}を{書|か}く（　　）、{多|おお}くの{資料|しりょう}を{集|あつ}めた。","options":["{一方|いっぽう}で","にあたって","ばかりか","くせに"],"answer":1,"vi":"Khi (chuẩn bị) viết luận văn tốt nghiệp, tôi đã thu thập rất nhiều tài liệu.","explain":"にあたって: trước khi bắt tay vào việc quan trọng thì chuẩn bị. 一方で là đối lập, ばかりか là 'không những', くせに là 'vậy mà' (chê trách)."}],
  "1.3": [{"q":"{窓|まど}を{開|あ}けた（　　）、{強|つよ}い{風|かぜ}で{書類|しょるい}が{飛|と}んでしまった。","options":["{上|うえ}で","からには","とたん","{末|すえ}に"],"answer":2,"vi":"Vừa mở cửa sổ thì giấy tờ đã bị gió mạnh thổi bay mất.","explain":"Vた＋とたん: vừa làm xong thì việc bất ngờ xảy ra. 上で là làm trước để chuẩn bị, からには là 'một khi đã', 末に là 'sau một quá trình dài'."},{"q":"{彼|かれ}は{椅子|いす}から{立|た}ち{上|あ}がった（　　）、{急|きゅう}に{倒|たお}れてしまった。","options":["{上|うえ}で","からには","あげく","とたんに"],"answer":3,"vi":"Anh ấy vừa đứng dậy khỏi ghế thì đột nhiên ngã quỵ.","explain":"とたんに diễn tả việc bất ngờ xảy ra ngay sau hành động. 上で là trình tự có chủ ý, からには là 'một khi đã', あげく là kết quả xấu sau thời gian dài."}],
  "1.4": [{"q":"{空|そら}が{急|きゅう}に{暗|くら}くなった（　　）、{激|はげ}しい{雨|あめ}が{降|ふ}り{出|だ}した。","options":["かと{思|おも}うと","からには","{上|うえ}で","{末|すえ}に"],"answer":0,"vi":"Trời vừa tối sầm lại thì mưa lớn đã đổ xuống.","explain":"Vた＋かと思うと: vừa mới… thì đã (việc bất ngờ). からには là 'một khi đã', 上で là trình tự chuẩn bị, 末に là 'sau một quá trình dài'."},{"q":"{赤|あか}ちゃんは{泣|な}いていた（　　）、もう{笑|わら}っている。","options":["からには","かと{思|おも}ったら","{以上|いじょう}","{最中|さいちゅう}に"],"answer":1,"vi":"Em bé vừa mới khóc đó mà giờ đã cười rồi.","explain":"かと思ったら dùng cho hành động của người khác, vế sau thay đổi bất ngờ. からには/以上 là 'một khi đã… thì', 最中に là bị cắt ngang khi đang làm."}],
  "1.5": [{"q":"ベルが{鳴|な}った（　　）、{生徒|せいと}たちは{教室|きょうしつ}を{飛|と}び{出|だ}した。","options":["{上|うえ}で","からには","か{鳴|な}らないかのうちに","{末|すえ}に"],"answer":2,"vi":"Chuông vừa reo (chưa dứt) thì học sinh đã lao ra khỏi lớp.","explain":"～たか～ないかのうちに: gần như cùng lúc, việc sau xảy ra ngay. 上で là trình tự có chủ ý, からには là 'một khi đã', 末に là 'sau thời gian dài'."},{"q":"{彼|かれ}は{布団|ふとん}に{入|はい}る（　　）、もう{寝|ね}てしまった。","options":["{際|さい}に","ばかりか","{一方|いっぽう}で","か{入|はい}らないかのうちに"],"answer":3,"vi":"Anh ấy vừa chui vào chăn là đã ngủ mất rồi.","explain":"か～ないかのうちに nhấn mạnh việc xảy ra ngay lập tức. 際に là cách nói trang trọng có chủ ý, ばかりか là 'không những', 一方で là đối lập."}],
  "2.0": [{"q":"{大事|だいじ}な{会議|かいぎ}の（　　）に、{携帯電話|けいたいでんわ}が{鳴|な}り{出|だ}した。","options":["{最中|さいちゅう}","{上|うえ}","ため","わり"],"answer":0,"vi":"Đúng lúc đang họp quan trọng thì điện thoại di động reo lên.","explain":"Nの＋最中に: đang lúc làm gì thì có việc bất ngờ gây cản trở. 上に là 'hơn nữa', ために chỉ mục đích/nguyên nhân, わりに là 'so với… thì' – không hợp."},{"q":"{料理|りょうり}を{作|つく}っている（　　）に、{急|きゅう}にガスが{止|と}まってしまった。","options":["ため","{最中|さいちゅう}","わり","くせ"],"answer":1,"vi":"Đang nấu ăn dở thì đột nhiên ga bị ngắt.","explain":"Vている＋最中に diễn tả việc bị cắt ngang. ために là mục đích/nguyên nhân, わりに là 'so với', くせに là 'vậy mà' – đều sai nghĩa."}],
  "2.1": [{"q":"この{町|まち}の{人口|じんこう}は{年々|ねんねん}{減|へ}る（　　）。","options":["ところだ","べきだ","{一方|いっぽう}だ","ことだ"],"answer":2,"vi":"Dân số của thị trấn này cứ ngày càng giảm.","explain":"Vる＋一方だ: thay đổi liên tục theo một chiều, hợp với 年々. ところだ là 'sắp làm', べきだ là 'nên', ことだ là lời khuyên."},{"q":"{薬|くすり}を{飲|の}んでも、{熱|ねつ}は{上|あ}がる（　　）。","options":["ことだ","ところだ","べきだ","ばかりだ"],"answer":3,"vi":"Dù đã uống thuốc nhưng sốt vẫn cứ tăng lên mãi.","explain":"Vる＋ばかりだ: cứ thay đổi theo chiều xấu. ところだ là 'sắp làm', べきだ là 'nên', ことだ là lời khuyên – không hợp với 薬を飲んでも."}],
  "2.2": [{"q":"{長|なが}かった{夏休|なつやす}みが、まもなく（　　）。","options":["{終|お}わろうとしている","{終|お}わったばかりだ","{終|お}わる{一方|いっぽう}だ","{終|お}わったところだ"],"answer":0,"vi":"Kỳ nghỉ hè dài sắp sửa kết thúc.","explain":"Vよう＋としている: sắp sửa kết thúc, hợp với まもなく. ～たばかりだ/～たところだ là vừa mới xong, 一方だ là xu hướng ngày càng."},{"q":"{電車|でんしゃ}のドアが（　　）とき、{一人|ひとり}の{男性|だんせい}が{駆|か}け{込|こ}んできた。","options":["{閉|し}まった","{閉|し}まろうとした","{閉|し}まる{一方|いっぽう}の","{閉|し}まりがちな"],"answer":1,"vi":"Đúng lúc cửa tàu sắp đóng thì một người đàn ông lao vào.","explain":"閉まろうとしたとき: lúc cửa sắp sửa đóng. Cửa đã đóng (閉まった) thì không thể chạy vào; 一方の/がちな chỉ xu hướng, không hợp."}],
  "2.3": [{"q":"{地球|ちきゅう}の{平均|へいきん}{気温|きおん}は{少|すこ}しずつ{上昇|じょうしょう}し（　　）。","options":["かねる","ようがない","つつある","そうもない"],"answer":2,"vi":"Nhiệt độ trung bình của Trái Đất đang dần dần tăng lên.","explain":"Vます＋つつある: đang trong quá trình thay đổi, hợp với 少しずつ. かねる là 'khó có thể', ようがない là 'không có cách', そうもない là 'có vẻ không'."},{"q":"{事故|じこ}で{傷|きず}ついた{町|まち}は、{今|いま}{少|すこ}しずつ{元|もと}の{姿|すがた}を{取|と}り{戻|もど}し（　　）。","options":["そうもない","かねる","ようがない","つつある"],"answer":3,"vi":"Thị trấn bị tổn thương vì tai nạn giờ đang dần lấy lại dáng vẻ ban đầu.","explain":"つつある diễn tả sự thay đổi đang diễn ra từng chút. そうもない, かねる, ようがない đều mang nghĩa phủ định, mâu thuẫn với 少しずつ."}],
  "2.4": [{"q":"{彼|かれ}は{窓|まど}の{外|そと}の{景色|けしき}を{眺|なが}め（　　）、{静|しず}かにコーヒーを{飲|の}んでいた。","options":["つつ","{次第|しだい}","かねて","かけて"],"answer":0,"vi":"Anh ấy vừa ngắm cảnh ngoài cửa sổ vừa lặng lẽ uống cà phê.","explain":"Vます＋つつ: vừa… vừa… (văn viết của ながら). 次第 là 'ngay sau khi', かねて là 'khó có thể', かけて là 'làm dở'."},{"q":"{専門家|せんもんか}の{意見|いけん}を{参考|さんこう}にし（　　）、{新|あたら}しい{制度|せいど}を{検討|けんとう}していく。","options":["{次第|しだい}","つつ","がちで","かねて"],"answer":1,"vi":"Chúng tôi sẽ vừa tham khảo ý kiến chuyên gia vừa xem xét chế độ mới.","explain":"つつ nối hai hành động đồng thời. 次第 là 'ngay sau khi', がちで là 'hay có khuynh hướng', かねて là 'khó có thể'."}],
  "2.5": [{"q":"{若|わか}い（　　）、いろいろな{国|くに}を{旅行|りょこう}しておきたい。","options":["{上|うえ}に","くせに","うちに","わりに"],"answer":2,"vi":"Tôi muốn đi du lịch nhiều nước khi còn trẻ.","explain":"A＋うちに: tranh thủ làm trong lúc trạng thái còn, trước khi thay đổi. 上に là 'hơn nữa', くせに là 'vậy mà', わりに là 'so với… thì'."},{"q":"{何度|なんど}も{話|はな}している（　　）、{彼|かれ}のことが{好|す}きになってきた。","options":["{最中|さいちゅう}に","くせに","わりに","うちに"],"answer":3,"vi":"Trong lúc nói chuyện nhiều lần, tôi đã dần thích anh ấy.","explain":"Vている＋うちに: trong lúc làm thì trạng thái dần thay đổi. 最中に là bị cắt ngang đột ngột, くせに là 'vậy mà', わりに là 'so với… thì'."}],
  "3.0": [{"q":"{病気|びょうき}になっ（　　）、{健康|けんこう}のありがたさがわかった。","options":["てはじめて","てまで","てからでないと","た{上|うえ}で"],"answer":0,"vi":"Phải đến khi bị bệnh tôi mới hiểu được giá trị của sức khỏe.","explain":"Vて＋はじめて: phải trải qua việc gì mới nhận ra. てまで là 'đến mức', てからでないと cần vế sau phủ định, た上で là chuẩn bị có chủ đích."},{"q":"{一人|ひとり}{暮|ぐ}らしをし（　　）、{家事|かじ}の{大変|たいへん}さを{知|し}った。","options":["た{上|うえ}で","てはじめて","てからでないと","てまで"],"answer":1,"vi":"Phải sống một mình tôi mới biết việc nhà vất vả thế nào.","explain":"てはじめて diễn tả nhận thức mới có sau trải nghiệm. た上で là làm trước rồi mới làm việc sau, てからでないと cần vế phủ định, てまで là 'đến mức'."}],
  "3.1": [{"q":"{家族|かぞく}とよく{相談|そうだん}した（　　）、{転職|てんしょく}するかどうか{決|き}めます。","options":["とたん","きり","{上|うえ}で","ばかりに"],"answer":2,"vi":"Sau khi bàn bạc kỹ với gia đình, tôi sẽ quyết định có chuyển việc hay không.","explain":"Vた＋上で: làm việc trước như bước chuẩn bị rồi mới làm việc sau. とたん là việc bất ngờ, きり là 'rồi thôi', ばかりに là 'chỉ vì' (kết quả xấu)."},{"q":"{契約|けいやく}の{内容|ないよう}をご{確認|かくにん}の（　　）、こちらにサインをお{願|ねが}いします。","options":["おかげで","せいで","{最中|さいちゅう}も","{上|うえ}"],"answer":3,"vi":"Sau khi xác nhận nội dung hợp đồng, xin vui lòng ký vào đây.","explain":"Nの＋上 (bỏ で): sau khi làm xong N thì mới làm việc sau. おかげで/せいで chỉ nguyên nhân, 最中も là 'cả trong lúc đang'."}],
  "3.2": [{"q":"{資料|しりょう}が{届|とど}き（　　）、すぐにお{送|おく}りします。","options":["{次第|しだい}","つつ","ながら","かねて"],"answer":0,"vi":"Ngay khi tài liệu đến, tôi sẽ gửi cho anh/chị.","explain":"Vます＋次第: ngay sau khi việc trước xong thì làm việc sau. つつ/ながら là 'vừa… vừa', かねて không hợp nghĩa."},{"q":"{詳|くわ}しいことが{分|わ}かり（　　）、ご{連絡|れんらく}いたします。","options":["つつ","{次第|しだい}","ながら","がちで"],"answer":1,"vi":"Ngay khi biết được chi tiết, tôi sẽ liên lạc với quý khách.","explain":"次第 dùng khi hứa làm ngay sau một sự việc. つつ/ながら là đồng thời, がちで là 'hay có khuynh hướng'."}],
  "3.3": [{"q":"{日本|にほん}に{来|き}て（　　）、{一度|いちど}も{国|くに}に{帰|かえ}っていない。","options":["はじめて","からでないと","{以来|いらい}","まで"],"answer":2,"vi":"Kể từ khi đến Nhật, tôi chưa về nước lần nào.","explain":"Vて＋以来: từ sau sự kiện đó, trạng thái cứ tiếp diễn. てはじめて là nhận ra lần đầu, てからでないと là 'nếu chưa… thì không', てまで là 'đến mức'."},{"q":"{大学|だいがく}を{卒業|そつぎょう}して（　　）、{彼|かれ}とはずっと{会|あ}っていない。","options":["はじめて","からでないと","まで","{以来|いらい}"],"answer":3,"vi":"Kể từ khi tốt nghiệp đại học, tôi không gặp anh ấy suốt.","explain":"て以来 đi với ずっと diễn tả tình trạng kéo dài đến nay. はじめて là nhận ra lần đầu, からでないと là 'nếu chưa… thì không', てまで là 'đến mức'."}],
  "3.4": [{"q":"{代金|だいきん}をお{支払|しはら}いいただいて（　　）、{商品|しょうひん}はお{渡|わた}しできません。","options":["からでないと","{以来|いらい}","まで","はじめて"],"answer":0,"vi":"Nếu quý khách chưa thanh toán thì chúng tôi không thể giao hàng.","explain":"てからでないと＋phủ định: chưa làm A thì không thể B. 以来 là trạng thái kéo dài, まで là 'đến mức', はじめて đi với vế khẳng định."},{"q":"{医者|いしゃ}の{許可|きょか}をもらって（　　）、{運動|うんどう}を{再開|さいかい}してはいけない。","options":["はじめて","からでなければ","{以来|いらい}","まで"],"answer":1,"vi":"Nếu chưa được bác sĩ cho phép thì không được tập thể dục lại.","explain":"てからでなければ đi với vế sau phủ định/cấm đoán. はじめて đi với vế khẳng định, 以来 là trạng thái kéo dài, まで là 'đến mức'."}],
  "4.0": [{"q":"この{店|みせ}では、ラーメン（　　）、{様々|さまざま}な{日本|にほん}{料理|りょうり}が{味|あじ}わえる。","options":["からして","にわたって","をはじめ","を{通|つう}じて"],"answer":2,"vi":"Ở quán này có thể thưởng thức nhiều món Nhật, tiêu biểu là ramen.","explain":"をはじめ: nêu một ví dụ tiêu biểu, vế sau có 様々な (nhiều). からして dùng cho đánh giá tiêu cực, にわたって/を通じて chỉ phạm vi thời gian/không gian."},{"q":"{社長|しゃちょう}（　　）{社員|しゃいん}{全員|ぜんいん}がパーティーに{出席|しゅっせき}した。","options":["にわたって","に{限|かぎ}って","に{対|たい}して","をはじめ"],"answer":3,"vi":"Toàn thể nhân viên, đứng đầu là giám đốc, đã tham dự bữa tiệc.","explain":"をはじめ đưa ra người tiêu biểu trong nhóm 全員. にわたって chỉ phạm vi, に限って chỉ sự bất thường, に対して chỉ đối tượng."}],
  "4.1": [{"q":"あのレストランは{店員|てんいん}の{態度|たいど}（　　）{悪|わる}いので、もう{行|い}きたくない。","options":["からして","にこたえて","にわたって","に{応|おう}じて"],"answer":0,"vi":"Nhà hàng đó ngay cả thái độ nhân viên đã tệ rồi nên tôi không muốn đến nữa.","explain":"からして: lấy một chi tiết nhỏ để đánh giá tiêu cực toàn thể. にこたえて là 'đáp ứng', にわたって chỉ phạm vi, に応じて là 'tùy theo'."},{"q":"この{小説|しょうせつ}はタイトル（　　）{暗|くら}い{感|かん}じがして、{読|よ}む{気|き}にならない。","options":["を{通|とお}して","からして","をもとに","にかけては"],"answer":1,"vi":"Cuốn tiểu thuyết này ngay từ cái tựa đã thấy u ám, tôi chẳng muốn đọc.","explain":"からして đưa ví dụ nhỏ (tựa đề) để đánh giá cả cuốn sách. を通して là 'thông qua', をもとに là 'dựa trên', にかけては nói về năng lực."}],
  "4.2": [{"q":"{会議|かいぎ}は{五|ご}{時間|じかん}（　　）{続|つづ}いたが、{結論|けつろん}は{出|で}なかった。","options":["をはじめ","からして","にわたって","に{際|さい}して"],"answer":2,"vi":"Cuộc họp kéo dài suốt 5 tiếng nhưng không đưa ra được kết luận.","explain":"にわたって đi với từ chỉ phạm vi (thời gian) và 続く. をはじめ nêu ví dụ, からして mang ý chê, に際して chỉ thời điểm."},{"q":"{台風|たいふう}の{影響|えいきょう}で、{広|ひろ}い{範囲|はんい}（　　）{停電|ていでん}が{発生|はっせい}した。","options":["に{限|かぎ}って","からして","をはじめ","にわたって"],"answer":3,"vi":"Do ảnh hưởng của bão, mất điện đã xảy ra trên một phạm vi rộng.","explain":"にわたって: hiện tượng lan khắp phạm vi (広い範囲). に限って chỉ sự bất thường, からして/をはじめ không chỉ phạm vi."}],
  "4.3": [{"q":"この{地域|ちいき}は{一年|いちねん}（　　）{気温|きおん}の{変化|へんか}が{少|すく}ない。","options":["を{通|つう}じて","に{際|さい}して","からして","をはじめ"],"answer":0,"vi":"Vùng này suốt cả năm nhiệt độ ít thay đổi.","explain":"を通じて (nghĩa ①): trong suốt một khoảng thời gian, trạng thái không đổi. に際して chỉ thời điểm sự kiện, からして/をはじめ không hợp."},{"q":"{友人|ゆうじん}（　　）{今|いま}の{妻|つま}と{知|し}り{合|あ}った。","options":["をもとに","を{通|とお}して","に{沿|そ}って","に{限|かぎ}り"],"answer":1,"vi":"Tôi quen vợ hiện tại thông qua một người bạn.","explain":"を通して (nghĩa ②): thông qua trung gian, phương tiện. をもとに là 'dựa trên tư liệu', に沿って là 'theo quy tắc', に限り là 'chỉ riêng'."}],
  "4.4": [{"q":"{声|こえ}の（　　）{叫|さけ}んだが、{誰|だれ}も{来|こ}なかった。","options":["ため","せい","{限|かぎ}り","{上|うえ}"],"answer":2,"vi":"Tôi đã hét hết sức mình nhưng không ai đến cả.","explain":"Nの＋限り: hết mức (声の限り = hết cỡ giọng). ため/せい chỉ mục đích/nguyên nhân, 上 là 'sau khi/hơn nữa' – không hợp."},{"q":"{見渡|みわた}す（　　）、{一面|いちめん}の{花畑|はなばたけ}が{広|ひろ}がっていた。","options":["{一方|いっぽう}","くせに","ばかりか","{限|かぎ}り"],"answer":3,"vi":"Trải dài khắp tầm mắt là cả một cánh đồng hoa.","explain":"見渡す限り: toàn bộ phạm vi nhìn thấy được. 一方 là đối lập, くせに là 'vậy mà', ばかりか là 'không những'."}],
  "4.5": [{"q":"{時間|じかん}はたっぷりあるから、{好|す}きな（　　）{遊|あそ}んでいいよ。","options":["だけ","{上|うえ}に","くせに","わりに"],"answer":0,"vi":"Thời gian còn nhiều nên con cứ chơi thỏa thích bao nhiêu tùy ý.","explain":"好きなだけ: đến mức tối đa mình muốn. 上に là 'hơn nữa', くせに là 'vậy mà', わりに là 'so với… thì'."},{"q":"{言|い}いたいことがあるなら、{言|い}いたい（　　）{言|い}えばいい。","options":["ばかりか","だけ","くせに","{一方|いっぽう}"],"answer":1,"vi":"Nếu có điều muốn nói thì cứ nói hết những gì muốn nói.","explain":"～たいだけ～: làm hết mức mong muốn, động từ lặp lại trước sau だけ. ばかりか là 'không những', くせに là 'vậy mà', 一方 là đối lập."}],
  "5.0": [{"q":"{本日|ほんじつ}ご{来店|らいてん}のお{客様|きゃくさま}（　　）、{全品|ぜんぴん}{二|に}{割引|わりびき}いたします。","options":["からして","にわたって","に{限|かぎ}り","をはじめ"],"answer":2,"vi":"Chỉ riêng quý khách đến cửa hàng hôm nay, chúng tôi giảm giá 20% tất cả sản phẩm.","explain":"に限り: ưu đãi đặc biệt chỉ dành cho đối tượng nhất định, dùng trong thông báo. からして mang ý chê, にわたって chỉ phạm vi, をはじめ nêu ví dụ tiêu biểu."},{"q":"{先着|せんちゃく}{五十|ごじゅう}{名|めい}（　　）、{記念品|きねんひん}を{差|さ}し{上|あ}げます。","options":["にわたって","をはじめ","に{応|おう}じて","に{限|かぎ}り"],"answer":3,"vi":"Chỉ dành cho 50 người đến sớm nhất, chúng tôi sẽ tặng quà kỷ niệm.","explain":"に限り dùng trong thông báo ưu đãi giới hạn đối tượng. にわたって chỉ phạm vi trải dài, をはじめ nêu ví dụ tiêu biểu, に応じて là 'tùy theo'."}],
  "5.1": [{"q":"{雨|あめ}が{降|ふ}らない（　　）、{試合|しあい}は{予定|よてい}{通|どお}り{行|おこな}われます。","options":["{限|かぎ}り","くせに","ばかりか","{上|うえ}に"],"answer":0,"vi":"Chừng nào trời không mưa thì trận đấu sẽ diễn ra như dự kiến.","explain":"～ない限り: chừng nào điều kiện còn duy trì thì… くせに là 'vậy mà', ばかりか/上に là 'không những… mà còn'."},{"q":"{健康|けんこう}である（　　）、{働|はたら}き{続|つづ}けたいと{思|おも}っている。","options":["{上|うえ}に","{限|かぎ}り","{一方|いっぽう}","ばかりか"],"answer":1,"vi":"Chừng nào còn khỏe mạnh, tôi muốn tiếp tục làm việc.","explain":"である限り: trong lúc trạng thái còn tiếp diễn thì trạng thái khác cũng tiếp diễn. 上に/ばかりか là 'hơn nữa', 一方 là đối lập."}],
  "5.2": [{"q":"{私|わたし}が{調|しら}べた（　　）、この{薬|くすり}に{副作用|ふくさよう}はないようだ。","options":["{上|うえ}では","とたんに","{限|かぎ}りでは","ばかりに"],"answer":2,"vi":"Theo những gì tôi đã tìm hiểu, thuốc này có vẻ không có tác dụng phụ.","explain":"Vた＋限りでは: trong phạm vi thông tin mình có thì có thể nói… とたんに là việc bất ngờ, ばかりに là 'chỉ vì', 上では không dùng để giới hạn nguồn thông tin."},{"q":"{天気|てんき}{予報|よほう}を{見|み}た（　　）、{明日|あした}は{晴|は}れるそうだ。","options":["とたんに","ばかりに","{上|うえ}で","{限|かぎ}りでは"],"answer":3,"vi":"Theo những gì tôi xem dự báo thời tiết thì nghe nói ngày mai trời nắng.","explain":"限りでは đi với động từ tiếp nhận thông tin (見る, 聞く…). とたんに là việc bất ngờ, ばかりに là 'chỉ vì', 上で là trình tự có chủ ý."}],
  "5.3": [{"q":"いつも{遅刻|ちこく}する{田中|たなか}さんが、{今日|きょう}（　　）{一番|いちばん}に{来|き}た。","options":["に{限|かぎ}って","に{限|かぎ}らず","をはじめ","にわたって"],"answer":0,"vi":"Anh Tanaka lúc nào cũng đi muộn, riêng hôm nay lại đến sớm nhất.","explain":"に限って: riêng lần đó khác hẳn thường lệ. に限らず là 'không chỉ', をはじめ là 'tiêu biểu là', にわたって chỉ phạm vi trải dài."},{"q":"いつもは{混|こ}んでいる{店|みせ}なのに、その{日|ひ}（　　）お{客|きゃく}が{一人|ひとり}もいなかった。","options":["からして","に{限|かぎ}って","にわたって","を{通|つう}じて"],"answer":1,"vi":"Quán lúc nào cũng đông, vậy mà riêng hôm đó lại không có một vị khách nào.","explain":"に限って nhấn mạnh 'chỉ riêng lần đó' khác bình thường. にわたって/を通じて chỉ phạm vi/suốt, からして là đánh giá tiêu cực."}],
  "5.4": [{"q":"{急|いそ}いでいる{時|とき}（　　）、{電車|でんしゃ}が{遅|おく}れるんだから{困|こま}る。","options":["に{際|さい}して","にあたって","に{限|かぎ}って","に{応|おう}じて"],"answer":2,"vi":"Cứ đúng lúc đang vội là tàu lại trễ, thật khổ.","explain":"に限って＋việc xấu: thể hiện sự bất mãn 'cứ đúng lúc…'. に際して/にあたって chỉ thời điểm trang trọng, に応じて là 'tùy theo'."},{"q":"{傘|かさ}を{持|も}って{出|で}なかった{日|ひ}（　　）、{大雨|おおあめ}が{降|ふ}る。","options":["をはじめ","からして","にわたって","に{限|かぎ}って"],"answer":3,"vi":"Cứ đúng hôm không mang ô ra ngoài là trời lại mưa to.","explain":"に限って diễn tả chuyện xấu cứ xảy ra đúng lúc đó, mang ý bất mãn. をはじめ/からして/にわたって không có nghĩa này."}],
  "5.5": [{"q":"まじめな{山田|やまだ}さん（　　）、{嘘|うそ}をつくはずがない。","options":["に{限|かぎ}って","にわたって","をはじめ","に{対|たい}して"],"answer":0,"vi":"Riêng anh Yamada nghiêm túc thì chắc chắn không thể nói dối.","explain":"に限って＋phủ định: tin chắc riêng người đó không làm điều xấu. にわたって chỉ phạm vi, をはじめ nêu ví dụ, に対して chỉ đối tượng."},{"q":"うちの{会社|かいしゃ}の{製品|せいひん}（　　）、そんな{事故|じこ}を{起|お}こすことはありません。","options":["にわたって","に{限|かぎ}って","をもとに","に{沿|そ}って"],"answer":1,"vi":"Riêng sản phẩm của công ty chúng tôi thì không bao giờ gây ra tai nạn như vậy.","explain":"に限って＋ことはない: khẳng định chắc chắn không xảy ra. にわたって chỉ phạm vi, をもとに/に沿って là 'dựa trên/theo'."}],
  "6.0": [{"q":"この{公園|こうえん}は{週末|しゅうまつ}（　　）、{平日|へいじつ}もたくさんの{人|ひと}でにぎわっている。","options":["に{限|かぎ}って","からして","に{限|かぎ}らず","に{限|かぎ}り"],"answer":2,"vi":"Công viên này không chỉ cuối tuần mà cả ngày thường cũng đông người.","explain":"に限らず＋も: không chỉ phạm vi đó mà rộng hơn. に限って/に限り lại giới hạn vào một đối tượng, mâu thuẫn với 平日も."},{"q":"{日本|にほん}のアニメは、{子|こ}ども（　　）{大人|おとな}にも{人気|にんき}がある。","options":["に{対|たい}して","に{応|おう}じて","にかけては","に{限|かぎ}らず"],"answer":3,"vi":"Anime Nhật Bản không chỉ được trẻ em mà cả người lớn cũng yêu thích.","explain":"に限らず đi với も để mở rộng phạm vi. に対して chỉ đối tượng/đối lập, に応じて là 'tùy theo', にかけては nói về năng lực."}],
  "6.1": [{"q":"{彼|かれ}は{英語|えいご}（　　）、フランス{語|ご}や{中国語|ちゅうごくご}も{話|はな}せる。","options":["のみならず","に{限|かぎ}って","からして","に{関|かん}して"],"answer":0,"vi":"Anh ấy không chỉ nói được tiếng Anh mà còn nói được cả tiếng Pháp và tiếng Trung.","explain":"のみならず＋も: không chỉ… mà còn (cùng cấp độ). に限って chỉ sự bất thường, からして là đánh giá tiêu cực, に関して là 'về'."},{"q":"その{問題|もんだい}は{日本|にほん}（　　）、{世界|せかい}{全体|ぜんたい}にとっても{重要|じゅうよう}だ。","options":["に{際|さい}して","のみならず","にわたって","を{通|つう}じて"],"answer":1,"vi":"Vấn đề đó không chỉ quan trọng với Nhật Bản mà còn với cả thế giới.","explain":"のみならず (văn viết) thêm phạm vi khác với も. に際して chỉ thời điểm, にわたって/を通じて chỉ phạm vi trải dài."}],
  "6.2": [{"q":"{彼|かれ}は{約束|やくそく}の{時間|じかん}に{遅|おく}れた（　　）、{謝|あやま}りもしなかった。","options":["とたん","{上|うえ}で","ばかりか","からには"],"answer":2,"vi":"Anh ta không những đến trễ giờ hẹn mà còn chẳng xin lỗi.","explain":"ばかりか: không những… mà còn (điều ngoài dự đoán) đi với も. とたん là việc bất ngờ ngay sau, 上で là trình tự, からには là 'một khi đã'."},{"q":"この{薬|くすり}は{効|き}かない（　　）、{副作用|ふくさよう}まである。","options":["{限|かぎ}り","うちに","{以上|いじょう}","ばかりか"],"answer":3,"vi":"Thuốc này không những không hiệu quả mà còn có cả tác dụng phụ.","explain":"ばかりか＋まで: thêm điều tệ hơn. 限り là 'chừng nào', うちに là 'trong lúc', 以上 là 'một khi đã' – không hợp nghĩa."}],
  "6.3": [{"q":"この{料理|りょうり}{教室|きょうしつ}には、{女性|じょせい}（　　）、{男性|だんせい}も{大勢|おおぜい}{参加|さんか}している。","options":["はもとより","をもとに","に{限|かぎ}って","に{対|たい}して"],"answer":0,"vi":"Lớp học nấu ăn này phụ nữ thì đương nhiên rồi, cả nam giới cũng tham gia rất đông.","explain":"はもとより: điều đương nhiên, thêm vào cái khác với も. をもとに là 'dựa trên', に限って chỉ sự bất thường, に対して chỉ đối lập."},{"q":"{彼|かれ}はスポーツ{万能|ばんのう}で、サッカー（　　）、{水泳|すいえい}やテニスも{得意|とくい}だ。","options":["にかけては","はもとより","をめぐって","からして"],"answer":1,"vi":"Anh ấy giỏi mọi môn thể thao, bóng đá thì khỏi nói, cả bơi lội và tennis cũng giỏi.","explain":"はもとより＋も: cái này đương nhiên, cái kia cũng vậy. にかけては chỉ một lĩnh vực giỏi nhất nên mâu thuẫn với も, をめぐって là tranh luận."}],
  "6.4": [{"q":"このアパートは{駅|えき}から{近|ちか}い（　　）、{家賃|やちん}も{安|やす}い。","options":["くせに","{一方|いっぽう}","{上|うえ}に","{限|かぎ}り"],"answer":2,"vi":"Căn hộ này đã gần ga lại còn rẻ tiền thuê.","explain":"上に: hơn nữa, hai vế cùng đánh giá tốt. くせに là chê trách, 一方 là đối lập, 限り là điều kiện."},{"q":"{昨日|きのう}は{道|みち}に{迷|まよ}った（　　）、{雨|あめ}にも{降|ふ}られて{大変|たいへん}だった。","options":["{上|うえ}で","とたん","からには","{上|うえ}に"],"answer":3,"vi":"Hôm qua tôi đã bị lạc đường lại còn bị dính mưa, thật vất vả.","explain":"上に nối hai việc cùng xấu, có も ở vế sau. 上で là 'sau khi (chuẩn bị)', とたん là bất ngờ ngay sau, からには là 'một khi đã'."}],
  "7.0": [{"q":"{今回|こんかい}の{事故|じこ}の{原因|げんいん}（　　）、{現在|げんざい}{調査|ちょうさ}を{進|すす}めております。","options":["に{関|かん}して","にかけては","に{限|かぎ}って","にこたえて"],"answer":0,"vi":"Về nguyên nhân của vụ tai nạn lần này, hiện chúng tôi đang tiến hành điều tra.","explain":"に関して: liên quan đến nội dung, đi với 調査. にかけては nói về năng lực, に限って chỉ sự bất thường, にこたえて là đáp ứng kỳ vọng."},{"q":"{新|あたら}しいサービス（　　）ご{質問|しつもん}がございましたら、お{気軽|きがる}にお{問|と}い{合|あ}わせください。","options":["にかけての","に{関|かん}する","に{沿|そ}った","をめぐる"],"answer":1,"vi":"Nếu có câu hỏi liên quan đến dịch vụ mới, xin đừng ngại liên hệ.","explain":"N＋に関する＋N: câu hỏi liên quan đến N. をめぐる dùng cho tranh luận, に沿った là 'theo quy tắc', にかけての chỉ phạm vi thời gian."}],
  "7.1": [{"q":"{遺産|いさん}（　　）、{兄弟|きょうだい}の{間|あいだ}で{争|あらそ}いが{起|お}きた。","options":["に{応|おう}じて","にかけては","をめぐって","に{沿|そ}って"],"answer":2,"vi":"Xoay quanh chuyện thừa kế, giữa các anh em đã nổ ra tranh chấp.","explain":"をめぐって: nhiều bên tranh chấp xoay quanh một vấn đề, đi với 争い. に応じて là 'tùy theo', にかけては là năng lực, に沿って là 'theo'."},{"q":"{新|あたら}しい{空港|くうこう}の{建設|けんせつ}（　　）、{賛成派|さんせいは}と{反対派|はんたいは}が{激|はげ}しく{対立|たいりつ}している。","options":["に{基|もと}づいて","にこたえて","{向|む}けに","をめぐって"],"answer":3,"vi":"Xoay quanh việc xây sân bay mới, phe tán thành và phe phản đối đang đối đầu gay gắt.","explain":"をめぐって đi với 対立, chủ thể số nhiều. に基づいて là 'căn cứ vào', にこたえて là 'đáp ứng', 向けに là 'dành cho'."}],
  "7.2": [{"q":"{料理|りょうり}の{腕|うで}（　　）、{彼|かれ}の{右|みぎ}に{出|で}る{者|もの}はいない。","options":["にかけては","をめぐって","に{対|たい}して","に{沿|そ}って"],"answer":0,"vi":"Về tài nấu ăn thì không ai vượt qua được anh ấy.","explain":"にかけては đi với từ chỉ năng lực, vế sau khẳng định giỏi nhất. をめぐって là tranh luận, に対して là đối tượng, に沿って là 'theo'."},{"q":"{数学|すうがく}は{苦手|にがて}だが、{記憶力|きおくりょく}（　　）{誰|だれ}にも{負|ま}けない{自信|じしん}がある。","options":["をもとに","にかけては","に{限|かぎ}って","に{伴|ともな}って"],"answer":1,"vi":"Tôi kém toán nhưng về khả năng ghi nhớ thì tôi tự tin không thua ai.","explain":"にかけては＋誰にも負けない là cách nói điển hình về năng lực. をもとに là 'dựa trên', に限って chỉ sự bất thường, に伴って là 'cùng với'."}],
  "7.3": [{"q":"{店員|てんいん}はお{客様|きゃくさま}（　　）{丁寧|ていねい}な{言葉|ことば}を{使|つか}わなければならない。","options":["にかけては","をめぐって","に{対|たい}して","に{限|かぎ}って"],"answer":2,"vi":"Nhân viên phải dùng lời lẽ lịch sự đối với khách hàng.","explain":"に対して chỉ đối tượng mà hành vi, thái độ hướng tới. にかけては là năng lực, をめぐって là tranh luận, に限って chỉ sự bất thường."},{"q":"{市民|しみん}の{苦情|くじょう}（　　）、{市|し}はまだ{何|なん}の{回答|かいとう}もしていない。","options":["に{際|さい}して","をはじめ","からして","に{対|たい}して"],"answer":3,"vi":"Đối với những phàn nàn của người dân, thành phố vẫn chưa có bất kỳ phản hồi nào.","explain":"に対して: hành động (回答) hướng trực tiếp đến đối tượng. に際して chỉ thời điểm, をはじめ nêu ví dụ, からして là đánh giá tiêu cực."}],
  "7.4": [{"q":"{兄|あに}がおとなしい{性格|せいかく}なの（　　）、{弟|おとうと}はとても{活発|かっぱつ}だ。","options":["に{対|たい}して","に{関|かん}して","に{伴|ともな}って","に{応|おう}じて"],"answer":0,"vi":"Trái với người anh có tính trầm lặng, người em lại rất năng động.","explain":"～のに対して: so sánh hai chủ thể đối lập. に関して là 'về', に伴って là 'cùng với', に応じて là 'tùy theo'."},{"q":"{都市部|としぶ}では{人口|じんこう}が{増|ふ}えているの（　　）、{農村|のうそん}では{減|へ}り{続|つづ}けている。","options":["に{関|かん}して","に{対|たい}して","をめぐって","にかけては"],"answer":1,"vi":"Trái với việc dân số ở thành thị đang tăng, ở nông thôn dân số tiếp tục giảm.","explain":"のに対して nêu hai mặt trái ngược (tăng – giảm). に関して/をめぐって chỉ chủ đề, にかけては chỉ năng lực."}],
  "7.5": [{"q":"{消費者|しょうひしゃ}の{要望|ようぼう}（　　）、{会社|かいしゃ}は{新|あたら}しい{商品|しょうひん}を{開発|かいはつ}した。","options":["に{限|かぎ}って","をめぐって","にこたえて","にかけては"],"answer":2,"vi":"Đáp ứng nguyện vọng của người tiêu dùng, công ty đã phát triển sản phẩm mới.","explain":"にこたえて đi với từ chỉ nguyện vọng (要望), làm để đáp ứng. をめぐって là tranh luận, に限って chỉ sự bất thường, にかけては là năng lực."},{"q":"ファンの{声援|せいえん}（　　）、{選手|せんしゅ}たちは{最後|さいご}まで{全力|ぜんりょく}で{戦|たたか}った。","options":["をもとに","に{沿|そ}って","からして","にこたえて"],"answer":3,"vi":"Đáp lại sự cổ vũ của người hâm mộ, các cầu thủ đã chiến đấu hết sức đến phút cuối.","explain":"にこたえて: hành động để đáp lại kỳ vọng, cổ vũ. をもとに là 'dựa trên', に沿って là 'theo', からして là đánh giá tiêu cực."}],
  "8.0": [{"q":"この{映画|えいが}は{作者|さくしゃ}{自身|じしん}の{体験|たいけん}（　　）{作|つく}られた。","options":["をもとに","のもとで","{向|む}けに","にかけては"],"answer":0,"vi":"Bộ phim này được làm dựa trên trải nghiệm của chính tác giả.","explain":"をもとに: lấy làm nền tảng để tạo ra cái mới. のもとで là 'dưới sự…', 向けに là 'dành cho', にかけては nói về năng lực."},{"q":"{集|あつ}めたアンケートの{結果|けっか}（　　）、{新|あたら}しいメニューを{考|かんが}えた。","options":["にこたえて","をもとにして","をめぐって","にかけては"],"answer":1,"vi":"Dựa trên kết quả khảo sát đã thu thập, chúng tôi đã nghĩ ra thực đơn mới.","explain":"をもとにして: lấy dữ liệu làm cơ sở để tạo ra cái mới (メニュー). にこたえて đi với nguyện vọng, をめぐって là tranh luận, にかけては là năng lực."}],
  "8.1": [{"q":"{法律|ほうりつ}（　　）、{公平|こうへい}に{判断|はんだん}しなければならない。","options":["をめぐって","{向|む}けに","に{基|もと}づいて","にかけては"],"answer":2,"vi":"Phải phán xét công bằng căn cứ vào pháp luật.","explain":"に基づいて: căn cứ vào chuẩn mực rõ ràng (pháp luật). をめぐって là tranh luận, 向けに là 'dành cho', にかけては là năng lực."},{"q":"この{報告書|ほうこくしょ}は{実際|じっさい}の{調査|ちょうさ}データ（　　）{書|か}かれている。","options":["のもとで","に{限|かぎ}って","にこたえて","に{基|もと}づいて"],"answer":3,"vi":"Bản báo cáo này được viết căn cứ vào dữ liệu điều tra thực tế.","explain":"に基づいて đi với dữ liệu, kết quả điều tra. のもとで là 'dưới sự chỉ đạo', に限って chỉ sự bất thường, にこたえて là 'đáp ứng'."}],
  "8.2": [{"q":"{川|かわ}（　　）、{桜|さくら}の{木|き}が{並|なら}んでいる。","options":["に{沿|そ}って","をもとに","に{基|もと}づいて","のもとに"],"answer":0,"vi":"Dọc theo bờ sông, những cây anh đào xếp hàng.","explain":"に沿って: men theo, dọc theo. をもとに/に基づいて là dựa vào tư liệu, căn cứ, のもとに là 'dưới sự…'."},{"q":"{会議|かいぎ}は{事前|じぜん}に{配|くば}られた{議題|ぎだい}（　　）{進|すす}められた。","options":["をめぐって","に{沿|そ}って","{向|む}けに","にかけては"],"answer":1,"vi":"Cuộc họp được tiến hành theo chương trình nghị sự đã phát trước.","explain":"に沿って: tuân theo trình tự, kế hoạch đã định. をめぐって là tranh luận, 向けに là 'dành cho', にかけては là năng lực."}],
  "8.3": [{"q":"{有名|ゆうめい}な{先生|せんせい}の{指導|しどう}（　　）、{三年間|さんねんかん}ピアノを{学|まな}んだ。","options":["をもとに","にかけては","のもとで","{向|む}けに"],"answer":2,"vi":"Tôi đã học piano 3 năm dưới sự chỉ dạy của một giáo viên nổi tiếng.","explain":"のもとで: chịu ảnh hưởng, chỉ dẫn của người nào đó. をもとに là dựa trên tư liệu, にかけては là năng lực, 向けに là 'dành cho'."},{"q":"{両親|りょうしん}の{愛情|あいじょう}（　　）、{子|こ}どもたちはすくすくと{育|そだ}った。","options":["をめぐって","にかけては","に{基|もと}づいて","のもとで"],"answer":3,"vi":"Dưới tình yêu thương của cha mẹ, những đứa trẻ đã lớn lên khỏe mạnh.","explain":"のもとで: trong sự che chở, ảnh hưởng của… に基づいて đi với dữ liệu, quy tắc, をめぐって là tranh luận."}],
  "8.4": [{"q":"この{番組|ばんぐみ}は{小学生|しょうがくせい}（　　）{作|つく}られているので、{言葉|ことば}がやさしい。","options":["{向|む}けに","からして","をめぐって","にかけては"],"answer":0,"vi":"Chương trình này được làm dành cho học sinh tiểu học nên ngôn từ dễ hiểu.","explain":"N＋向けに: hướng tới đối tượng cụ thể, đi với 作る. からして là đánh giá tiêu cực, をめぐって là tranh luận, にかけては là năng lực."},{"q":"{外国人|がいこくじん}（　　）の{観光|かんこう}パンフレットが{駅|えき}に{置|お}いてある。","options":["をめぐって","{向|む}け","にかけて","に{伴|ともな}って"],"answer":1,"vi":"Ở nhà ga có đặt tờ rơi du lịch dành cho người nước ngoài.","explain":"N＋向けの＋N: thứ được làm dành cho đối tượng đó. をめぐって là tranh luận, にかけて chỉ phạm vi, に伴って là 'cùng với' – không chỉ đối tượng."}],
  "9.0": [{"q":"{年|とし}をとる（　　）、{体力|たいりょく}が{落|お}ちてきた。","options":["に{際|さい}して","{上|うえ}で","につれて","くせに"],"answer":2,"vi":"Càng có tuổi thì thể lực càng giảm sút.","explain":"につれて: một sự thay đổi dần kéo theo thay đổi khác. に際して là thời điểm đặc biệt, 上で là trình tự, くせに là 'vậy mà'."},{"q":"{山|やま}を{登|のぼ}る（　　）、{空気|くうき}が{冷|つめ}たくなってきた。","options":["にあたって","{限|かぎ}り","くせに","にしたがって"],"answer":3,"vi":"Càng leo lên núi, không khí càng lạnh.","explain":"にしたがって: thay đổi song song theo diễn biến. にあたって chỉ thời điểm bắt đầu, 限り là điều kiện/phạm vi, くせに là 'vậy mà'."}],
  "9.1": [{"q":"{経済|けいざい}の{発展|はってん}（　　）、{環境|かんきょう}{問題|もんだい}が{深刻|しんこく}になってきた。","options":["に{伴|ともな}って","にかけては","をもとに","に{限|かぎ}って"],"answer":0,"vi":"Cùng với sự phát triển kinh tế, vấn đề môi trường ngày càng nghiêm trọng.","explain":"Nする＋に伴って: sự thay đổi này kéo theo thay đổi khác. にかけては là năng lực, をもとに là 'dựa trên', に限って chỉ sự bất thường."},{"q":"{時代|じだい}の{変化|へんか}（　　）、{人々|ひとびと}の{働|はたら}き{方|かた}も{変|か}わってきた。","options":["にかけては","とともに","に{対|たい}して","をめぐって"],"answer":1,"vi":"Cùng với sự thay đổi của thời đại, cách làm việc của mọi người cũng thay đổi.","explain":"とともに: hai sự thay đổi diễn ra cùng nhau. にかけては là năng lực, に対して là đối tượng/đối lập, をめぐって là tranh luận."}],
  "9.2": [{"q":"{旅行|りょこう}に{行|い}けるかどうかは、{明日|あした}の{天気|てんき}（　　）。","options":["のせいだ","{向|む}けだ","{次第|しだい}だ","のおかげだ"],"answer":2,"vi":"Có đi du lịch được hay không là tùy vào thời tiết ngày mai.","explain":"N＋次第だ: kết quả phụ thuộc vào yếu tố đó (～かどうかは…次第だ). のせいだ/のおかげだ chỉ nguyên nhân đã xảy ra, 向けだ là 'dành cho'."},{"q":"{成功|せいこう}するかどうかは、あなたの{努力|どりょく}（　　）です。","options":["{向|む}け","のせい","のおかげ","{次第|しだい}"],"answer":3,"vi":"Thành công hay không là tùy vào nỗ lực của bạn.","explain":"次第です: quyết định phụ thuộc vào N, đi với かどうか. 向け là 'dành cho', のせい/のおかげ chỉ nguyên nhân của kết quả đã có."}],
  "9.3": [{"q":"{料金|りょうきん}は{利用|りよう}する{時間|じかん}（　　）{変|か}わります。","options":["に{応|おう}じて","に{関|かん}して","にかけては","をめぐって"],"answer":0,"vi":"Mức phí thay đổi tùy theo thời gian sử dụng.","explain":"に応じて: thay đổi cho tương ứng với yếu tố đó. に関して là 'về', にかけては là năng lực, をめぐって là tranh luận."},{"q":"{学生|がくせい}のレベル（　　）{教材|きょうざい}を{選|えら}ぶことが{大切|たいせつ}だ。","options":["にこたえて","に{応|おう}じて","からして","をはじめ"],"answer":1,"vi":"Việc chọn giáo trình phù hợp với trình độ của học sinh là rất quan trọng.","explain":"に応じて: điều chỉnh cho phù hợp với mức độ. にこたえて đi với nguyện vọng/kỳ vọng, からして/をはじめ không hợp nghĩa."}],
  "9.4": [{"q":"この{写真|しゃしん}を{見|み}る（　　）、{楽|たの}しかった{学生|がくせい}{時代|じだい}を{思|おも}い{出|だ}す。","options":["に{際|さい}して","にあたって","につけて","{限|かぎ}り"],"answer":2,"vi":"Mỗi khi nhìn bức ảnh này, tôi lại nhớ về thời sinh viên vui vẻ.","explain":"Vる＋につけて: mỗi khi… lại có cảm xúc (思い出す). に際して/にあたって chỉ thời điểm đặc biệt, 限り là phạm vi."},{"q":"{何|なに}か（　　）{母|はは}は{私|わたし}に{電話|でんわ}をかけてくる。","options":["に{限|かぎ}って","に{際|さい}して","をはじめ","につけて"],"answer":3,"vi":"Hễ có chuyện gì là mẹ lại gọi điện cho tôi.","explain":"何かにつけて là cách nói cố định 'hễ có chuyện gì'. に限って/に際して/をはじめ không kết hợp với 何か theo nghĩa này."}],
  "10.0": [{"q":"{引|ひ}っ{越|こ}しの{準備|じゅんび}で、{荷造|にづく}り（　　）{掃除|そうじ}やら、{毎日|まいにち}{大変|たいへん}だ。","options":["やら","にしろ","というか","といった"],"answer":0,"vi":"Vì chuẩn bị chuyển nhà, nào là đóng gói đồ đạc, nào là dọn dẹp, ngày nào cũng vất vả.","explain":"Cặp ～やら～やら liệt kê nhiều việc lộn xộn, kèm cảm giác vất vả. にしろ～にしろ là 'dù… hay…', というか là cách nói lựa chọn diễn đạt, không hợp."},{"q":"{初|はじ}めての{発表|はっぴょう}で、{恥|は}ずかしい（　　）{緊張|きんちょう}するやらで、{何|なに}を{言|い}ったか{覚|おぼ}えていない。","options":["というか","にしても","やら","ものの"],"answer":2,"vi":"Lần đầu thuyết trình, nào là xấu hổ, nào là căng thẳng, tôi chẳng nhớ mình đã nói gì.","explain":"Phía sau có 緊張するやら nên cần やら để tạo cặp ～やら～やら liệt kê nhiều cảm xúc. ものの (tuy… nhưng) và にしても (dù) không ghép cặp được."}],
  "10.1": [{"q":"{彼|かれ}の{行動|こうどう}は{大胆|だいたん}（　　）{無謀|むぼう}というか、{見|み}ているほうがはらはらする。","options":["というか","やら","にしろ","といった"],"answer":0,"vi":"Hành động của anh ấy, nói là táo bạo hay là liều lĩnh đây, người nhìn cũng thấy thót tim.","explain":"～というか～というか đưa ra hai cách đánh giá mà không chắc cách nào đúng hơn. やら dùng để liệt kê nhiều thứ, にしろ là 'dù… hay…', không hợp."},{"q":"あの{人|ひと}は{素直|すなお}というか{単純|たんじゅん}（　　）、{人|ひと}の{話|はなし}をすぐ{信|しん}じてしまう。","options":["にしても","といった","やら","というか"],"answer":3,"vi":"Người đó nói là thật thà hay là đơn giản đây, cứ nghe người khác nói là tin ngay.","explain":"Phía trước đã có 素直というか nên cần というか để thành cặp diễn đạt lưỡng lự giữa hai nhận xét. といった là liệt kê ví dụ, にしても là 'dù…'."}],
  "10.2": [{"q":"{賛成|さんせい}（　　）{反対|はんたい}にしろ、{自分|じぶん}の{意見|いけん}ははっきり{言|い}うべきだ。","options":["やら","というか","といった","にしろ"],"answer":3,"vi":"Dù là tán thành hay phản đối thì cũng nên nói rõ ý kiến của mình.","explain":"～にしろ～にしろ: dù trường hợp nào thì cũng như nhau, vế sau là phán đoán (べきだ). やら dùng liệt kê, というか là lưỡng lự cách diễn đạt."},{"q":"{行|い}くにしても{行|い}かない（　　）、{明日|あした}までに{連絡|れんらく}してください。","options":["にしても","やら","というか","ものの"],"answer":0,"vi":"Dù đi hay không đi thì cũng hãy liên lạc trước ngày mai.","explain":"Cặp đối lập 行く／行かない + ～にしても～にしても: dù thế nào cũng phải liên lạc. やら, というか không diễn tả 'dù… hay…'."}],
  "10.3": [{"q":"この{店|みせ}では、{醤油|しょうゆ}や{味噌|みそ}（　　）{日本|にほん}の{調味料|ちょうみりょう}が{何|なん}でも{手|て}に{入|はい}る。","options":["やら","にしろ","といった","というか"],"answer":2,"vi":"Ở cửa hàng này, các loại gia vị Nhật như xì dầu, miso thì thứ gì cũng mua được.","explain":"～といった + N: nêu ví dụ rồi gom lại bằng danh từ chung (日本の調味料). やら, にしろ, というか không nối trực tiếp với danh từ phía sau như vậy."},{"q":"{京都|きょうと}や{奈良|なら}（　　）{古|ふる}い{町|まち}には、{外国人|がいこくじん}{観光客|かんこうきゃく}が{多|おお}い。","options":["というか","といった","にしても","やら"],"answer":1,"vi":"Ở những thành phố cổ như Kyoto hay Nara có rất nhiều khách du lịch nước ngoài.","explain":"や～といった + N là cách liệt kê ví dụ rồi tóm lại bằng 古い町. にしても là 'dù', やら cần cặp ～やら～やら."}],
  "11.0": [{"q":"このマラソン{大会|たいかい}には、{年齢|ねんれい}や{性別|せいべつ}（　　）、{誰|だれ}でも{参加|さんか}できる。","options":["を{問|と}わず","もかまわず","はともかく","はさておき"],"answer":0,"vi":"Giải marathon này không phân biệt tuổi tác hay giới tính, ai cũng có thể tham gia.","explain":"～を問わず: không phân biệt điều kiện, hợp với 誰でも. もかまわず là bất chấp (mang ý tiêu cực), はともかく/はさておき là tạm gác lại, không hợp."},{"q":"この{公園|こうえん}は{季節|きせつ}（　　）、{多|おお}くの{人|ひと}でにぎわっている。","options":["もかまわず","はさておき","を{問|と}わず","につき"],"answer":2,"vi":"Công viên này bất kể mùa nào cũng đông đúc người.","explain":"季節を問わず = mùa nào cũng vậy. もかまわず là bất chấp, につき là 'vì' (thông báo), はさておき là tạm gác sang bên."}],
  "11.1": [{"q":"{天候|てんこう}（　　）、{試合|しあい}は{予定|よてい}{通|どお}り{行|おこな}われます。","options":["にかかわらず","もかまわず","はさておき","にもかかわらず"],"answer":0,"vi":"Bất kể thời tiết thế nào, trận đấu vẫn được tổ chức theo kế hoạch.","explain":"～にかかわらず: không liên quan đến (thời tiết tốt hay xấu). にもかかわらず là 'mặc dù' một sự thật cụ thể (cần 悪天候), もかまわず là bất chấp người khác."},{"q":"{参加|さんか}する、しない（　　）、{必|かなら}ず{返事|へんじ}をください。","options":["はともかく","にかかわりなく","もかまわず","からといって"],"answer":1,"vi":"Dù tham gia hay không thì cũng nhất định hãy trả lời.","explain":"Hai lựa chọn đối lập + ～にかかわりなく: không liên quan đến việc tham gia hay không. はともかく là tạm không bàn, からといって là 'chỉ vì… mà'."}],
  "11.2": [{"q":"{彼女|かのじょ}は{服|ふく}が{汚|よご}れるの（　　）、{泥|どろ}だらけの{犬|いぬ}を{抱|だ}きしめた。","options":["を{問|と}わず","にかかわらず","もかまわず","はさておき"],"answer":2,"vi":"Cô ấy ôm chầm lấy con chó lấm lem bùn đất, chẳng màng quần áo bị bẩn.","explain":"～のもかまわず: bất chấp, không bận tâm đến điều lẽ ra phải để ý. を問わず/にかかわらず là không phân biệt điều kiện, không hợp với hành động cụ thể này."},{"q":"その{男|おとこ}は{周|まわ}りの{迷惑|めいわく}（　　）、{電車|でんしゃ}の{中|なか}で{大声|おおごえ}で{電話|でんわ}していた。","options":["もかまわず","を{問|と}わず","はともかく","にかかわらず"],"answer":0,"vi":"Người đàn ông đó nói điện thoại oang oang trên tàu, bất chấp việc làm phiền người xung quanh.","explain":"迷惑もかまわず = không màng đến phiền toái gây cho người khác (ý phê phán). を問わず/にかかわらず chỉ 'không phân biệt', はともかく là tạm không bàn."}],
  "11.3": [{"q":"この{車|くるま}はデザイン（　　）、{燃費|ねんぴ}がとてもいい。","options":["を{問|と}わず","もかまわず","はともかく","にかかわらず"],"answer":2,"vi":"Chiếc xe này thiết kế thì chưa bàn, nhưng mức tiêu hao nhiên liệu rất tốt.","explain":"～はともかく: tạm không bàn A, ưu tiên nói về B. を問わず/にかかわらず là 'không phân biệt', もかまわず là bất chấp, không hợp."},{"q":"{結果|けっか}（　　）、{最後|さいご}まで{頑張|がんば}ったことは{評価|ひょうか}したい。","options":["もかまわず","につき","{次第|しだい}で","はともかくとして"],"answer":3,"vi":"Kết quả thì tạm không bàn, tôi muốn đánh giá cao việc đã cố gắng đến cùng.","explain":"～はともかくとして: gác kết quả lại, tập trung vào sự cố gắng. もかまわず (bất chấp), につき (vì), 次第で (tùy vào) không hợp nghĩa."}],
  "11.4": [{"q":"{前置|まえお}き（　　）、さっそく{本題|ほんだい}に{入|はい}りましょう。","options":["もかまわず","はさておき","を{問|と}わず","にかかわらず"],"answer":1,"vi":"Gác phần mở đầu sang một bên, chúng ta vào ngay vấn đề chính nhé.","explain":"～はさておき: tạm gác chuyện đó lại để nói chuyện quan trọng hơn. を問わず/にかかわらず là không phân biệt, もかまわず là bất chấp."},{"q":"{誰|だれ}が{悪|わる}いか（　　）、まずは{問題|もんだい}を{解決|かいけつ}することが{先|さき}だ。","options":["もかまわず","はさておき","につき","によって"],"answer":1,"vi":"Ai sai thì tạm gác lại, trước hết phải giải quyết vấn đề đã.","explain":"～はさておき: tạm để vấn đề ai đúng ai sai sang một bên. もかまわず (bất chấp), につき (vì), によって (tùy theo) không hợp nghĩa."}],
  "12.0": [{"q":"{一度|いちど}も{練習|れんしゅう}していないのだから、{試合|しあい}に{勝|か}てる（　　）。","options":["わけがない","わけではない","というものではない","どころではない"],"answer":0,"vi":"Vì chưa luyện tập lần nào nên không thể nào thắng trận được.","explain":"～わけがない phủ định mạnh khả năng xảy ra. わけではない là phủ định một phần 'không hẳn là', どころではない là 'không phải lúc để…'."},{"q":"あんなに{正直|しょうじき}な{彼|かれ}が{嘘|うそ}をつく（　　）。きっと{何|なに}かの{間違|まちが}いだ。","options":["わけではない","どころではない","わけがない","わけにはいかない"],"answer":2,"vi":"Người thật thà như anh ấy làm gì có chuyện nói dối. Chắc chắn là có nhầm lẫn gì đó.","explain":"わけがない: chắc chắn không thể có chuyện đó. わけではない chỉ phủ định một phần, わけにはいかない là 'không thể làm (vì lý do đạo lý)'."}],
  "12.1": [{"q":"{貯金|ちょきん}する（　　）、{毎月|まいつき}の{生活費|せいかつひ}も{足|た}りないくらいだ。","options":["どころか","わけがなく","ものか","わけではなく"],"answer":0,"vi":"Đừng nói là để dành tiền, đến tiền sinh hoạt mỗi tháng cũng không đủ.","explain":"～どころか: không những không A, mà ngay cả mức thấp hơn cũng không đạt. わけではなく (không phải là) và ものか (làm sao mà) không nối được ý này."},{"q":"{明日|あした}は{試験|しけん}なので、パーティー（　　）。","options":["にすぎない","に{違|ちが}いない","というものではない","どころではない"],"answer":3,"vi":"Vì mai thi nên không phải lúc để tiệc tùng.","explain":"N＋どころではない: hoàn cảnh không cho phép làm việc đó. にすぎない là 'chỉ là', に違いない là 'chắc chắn là', không hợp."}],
  "12.2": [{"q":"あんなまずい{店|みせ}には、{二度|にど}と{行|い}く（　　）。","options":["わけではない","ものだ","ものか","ことか"],"answer":2,"vi":"Cái quán dở tệ đó, đời nào tôi quay lại lần nữa!","explain":"～ものか: phủ định mạnh, thể hiện quyết tâm không làm (văn nói). ものだ là cảm thán/lẽ thường, ことか là cảm thán mức độ, không hợp với 二度と."},{"q":"{何度|なんど}{失敗|しっぱい}しても、{夢|ゆめ}を{諦|あきら}める（　　）。","options":["ものか","ものなら","ばかりだ","ことだ"],"answer":0,"vi":"Dù thất bại bao nhiêu lần, tôi cũng không đời nào từ bỏ ước mơ!","explain":"～ものか: quyết tâm mạnh 'không đời nào'. ことだ là lời khuyên 'nên', ものなら là 'nếu có thể', ばかりだ là 'chỉ toàn', đều sai nghĩa."}],
  "12.3": [{"q":"{料理|りょうり}が{嫌|きら}いな（　　）が、{忙|いそが}しくて{作|つく}る{時間|じかん}がないのだ。","options":["わけではない","はずだ","わけだ","ものだ"],"answer":0,"vi":"Không phải là tôi ghét nấu ăn, mà là bận quá không có thời gian nấu.","explain":"～わけではない…が: phủ định một phần rồi nêu lý do thật. はずだ (chắc là), わけだ (thảo nào), ものだ (lẽ thường) mâu thuẫn với vế giải thích phía sau."},{"q":"{全員|ぜんいん}が{賛成|さんせい}している（　　）が、{多|おお}くの{人|ひと}は{前向|まえむ}きだ。","options":["わけがない","ものか","どころではない","というわけではない"],"answer":3,"vi":"Không phải là tất cả mọi người đều tán thành, nhưng nhiều người có thái độ tích cực.","explain":"～というわけではない: không hẳn là tất cả. わけがない/ものか phủ định hoàn toàn, mâu thuẫn với 多くの人は前向き."}],
  "12.4": [{"q":"{値段|ねだん}が{高|たか}ければ{品質|ひんしつ}がいい（　　）。{安|やす}くてもいい{物|もの}はたくさんある。","options":["にすぎない","というものではない","どころではない","に{違|ちが}いない"],"answer":1,"vi":"Không phải cứ đắt là chất lượng tốt. Có nhiều đồ rẻ mà vẫn tốt.","explain":"～ば～というものではない: không phải cứ… là…. に違いない (chắc chắn) mâu thuẫn với câu sau, にすぎない (chỉ là) không hợp."},{"q":"{子|こ}どもは{厳|きび}しく{叱|しか}ればいい（　　）。{理由|りゆう}を{説明|せつめい}することが{大切|たいせつ}だ。","options":["に{決|き}まっている","にすぎない","わけだ","というものでもない"],"answer":3,"vi":"Trẻ con không phải cứ mắng nghiêm khắc là được. Giải thích lý do mới là quan trọng.","explain":"～ばいいというものでもない phủ định quan niệm 'cứ… là được'. に決まっている (chắc chắn) và わけだ (thảo nào) mâu thuẫn với câu sau."}],
  "13.0": [{"q":"「{一石二鳥|いっせきにちょう}」（　　）、{一|ひと}つのことで{二|ふた}つの{利益|りえき}を{得|え}ることだ。","options":["とは","といえば","といったら","となると"],"answer":0,"vi":"'Nhất cử lưỡng tiện' nghĩa là nhờ một việc mà được hai cái lợi.","explain":"N＋とは…ことだ dùng để định nghĩa. といえば là liên tưởng, といったら nhấn mạnh mức độ, となると là 'hễ nói đến', không phải định nghĩa."},{"q":"{日本語|にほんご}の「{積読|つんどく}」（　　）、{本|ほん}を{買|か}っても{読|よ}まずに{積|つ}んでおくことです。","options":["となると","といったら","にしては","とは"],"answer":3,"vi":"'Tsundoku' trong tiếng Nhật nghĩa là mua sách rồi không đọc mà chất đống đó.","explain":"とは dùng để giải thích nghĩa của từ. となると, といったら, にしては không dùng để định nghĩa."}],
  "13.1": [{"q":"A：{夏休|なつやす}みに{北海道|ほっかいどう}へ{行|い}ったんだ。B：{北海道|ほっかいどう}（　　）、{今|いま}ラーメンフェアをやっているらしいよ。","options":["といえば","とは","にしては","となると"],"answer":0,"vi":"A: Nghỉ hè tôi đã đi Hokkaido. B: Nhắc đến Hokkaido, nghe nói bây giờ đang có lễ hội mì ramen đấy.","explain":"といえば: lấy từ người kia vừa nói để liên tưởng sang chuyện khác. とは là định nghĩa, にしては là 'so với… thì', となると là 'hễ đến…'."},{"q":"{雨|あめ}がよく{降|ふ}りますね。{雨|あめ}（　　）、{傘|かさ}を{電車|でんしゃ}に{忘|わす}れてきてしまいました。","options":["とは","にしては","といえば","となると"],"answer":2,"vi":"Mưa nhiều nhỉ. Nhắc đến mưa, tôi lỡ để quên ô trên tàu điện mất rồi.","explain":"といえば chuyển đề tài từ từ vừa được nhắc tới. とは (định nghĩa) và にしては (so với) không hợp."}],
  "13.2": [{"q":"この{仕事|しごと}は{大変|たいへん}（　　）{大変|たいへん}だが、やりがいがある。","options":["というか","といえば","とはいえ","にしても"],"answer":1,"vi":"Công việc này nói vất vả thì cũng đúng là vất vả, nhưng rất đáng làm.","explain":"AといえばAだが: thừa nhận ở mức độ nào đó rồi nêu mặt khác. というか là lưỡng lự cách nói, とはいえ/にしても không lặp lại từ theo mẫu này."},{"q":"{彼|かれ}の{言|い}うことも{正|ただ}しい（　　）{正|ただ}しいが、{言|い}い{方|かた}がきつすぎる。","options":["にしろ","やら","というか","といえば"],"answer":3,"vi":"Điều anh ấy nói thì cũng đúng là đúng, nhưng cách nói quá gay gắt.","explain":"正しいといえば正しいが: công nhận một phần rồi phản bác. にしろ, やら, というか không tạo mẫu lặp từ này."}],
  "13.3": [{"q":"{京都|きょうと}（　　）、やはり{金閣寺|きんかくじ}や{清水寺|きよみずでら}を{思|おも}い{浮|う}かべる。","options":["とは","となると","にしては","というと"],"answer":3,"vi":"Nhắc đến Kyoto thì quả nhiên tôi nghĩ ngay đến chùa Kinkaku hay chùa Kiyomizu.","explain":"というと: nhắc đến thì liên tưởng ngay. とは là định nghĩa, にしては là 'so với', となると là 'hễ đến (thì thái độ thay đổi)'."},{"q":"A：{来週|らいしゅう}、{佐藤|さとう}さんが{来|く}るそうです。B：{佐藤|さとう}さん（　　）、{前|まえ}に{大阪|おおさか}{支社|ししゃ}にいた{方|かた}ですか。","options":["にかけては","となると","というと","にしては"],"answer":2,"vi":"A: Nghe nói tuần sau anh Sato sẽ đến. B: Anh Sato, có phải là người trước đây ở chi nhánh Osaka không?","explain":"というと dùng để xác nhận lại điều người kia nói. にかけては (về mặt… thì giỏi), にしては (so với) không hợp."}],
  "13.4": [{"q":"{父|ちち}は{普段|ふだん}は{無口|むくち}だが、{釣|つ}りのこと（　　）、{急|きゅう}によく{話|はな}すようになる。","options":["とは","となると","というより","にしては"],"answer":1,"vi":"Bố tôi bình thường ít nói, nhưng hễ nhắc đến chuyện câu cá là đột nhiên nói rất nhiều.","explain":"（のこと）となると: hễ đến chuyện đó là thái độ khác hẳn. とは là định nghĩa, というより là 'đúng hơn là', にしては là 'so với'."},{"q":"{兄|あに}は{勉強|べんきょう}は{苦手|にがて}だが、ゲーム（　　）{夢中|むちゅう}になって{何時間|なんじかん}でも{続|つづ}ける。","options":["とは","にしては","というと","となると"],"answer":3,"vi":"Anh trai tôi học kém, nhưng hễ đến game là say mê chơi bao nhiêu tiếng cũng được.","explain":"となると: hễ là chuyện đó thì trở nên khác thường. というと là liên tưởng/xác nhận, にしては là 'so với… thì'."}],
  "13.5": [{"q":"{頂上|ちょうじょう}から{見|み}た{景色|けしき}の{美|うつく}しさ（　　）、{言葉|ことば}では{表|あらわ}せないほどだった。","options":["といったら","とは","にしては","となると"],"answer":0,"vi":"Vẻ đẹp của phong cảnh nhìn từ đỉnh núi thì không lời nào tả xiết.","explain":"N＋といったら nhấn mạnh mức độ cực kỳ, không tả nổi. とは là định nghĩa, にしては là 'so với', となると là 'hễ đến'."},{"q":"{一人|ひとり}で{海外|かいがい}に{住|す}み{始|はじ}めたときの{心細|こころぼそ}さ（　　）、{今|いま}{思|おも}い{出|だ}しても{涙|なみだ}が{出|で}る。","options":["にしては","とは","といったら","からといって"],"answer":2,"vi":"Nỗi cô đơn khi bắt đầu sống một mình ở nước ngoài thì đến giờ nhớ lại vẫn còn rơi nước mắt.","explain":"といったら nhấn mạnh cảm xúc ở mức cực độ. にしては (so với), からといって (chỉ vì) không hợp."}],
  "14.0": [{"q":"{彼|かれ}は{熱|ねつ}がある（　　）、{会議|かいぎ}に{出席|しゅっせき}した。","options":["にかかわらず","にもかかわらず","おかげで","からといって"],"answer":1,"vi":"Mặc dù bị sốt, anh ấy vẫn tham dự cuộc họp.","explain":"にもかかわらず: mặc dù có sự thật đó mà vẫn… (gây bất ngờ). にかかわらず là 'bất kể', おかげで là 'nhờ', からといって là 'chỉ vì… mà không hẳn'."},{"q":"{十分|じゅうぶん}に{準備|じゅんび}した（　　）、{試験|しけん}に{落|お}ちてしまった。","options":["にかかわらず","おかげで","からには","にもかかわらず"],"answer":3,"vi":"Mặc dù đã chuẩn bị kỹ càng nhưng vẫn trượt kỳ thi.","explain":"にもかかわらず diễn tả kết quả trái với mong đợi. おかげで là 'nhờ', からには là 'một khi đã', にかかわらず là 'bất kể'."}],
  "14.1": [{"q":"{免許|めんきょ}は{取|と}った（　　）、{怖|こわ}くてまだ{一度|いちど}も{運転|うんてん}していない。","options":["からには","ばかりに","ものの","からといって"],"answer":2,"vi":"Tuy đã lấy được bằng lái nhưng vì sợ nên vẫn chưa lái lần nào.","explain":"～ものの: tuy A nhưng thực tế không như dự định. からには (một khi đã… thì phải), ばかりに (chỉ vì… mà), からといって (chỉ vì… mà không hẳn) không hợp."},{"q":"{暦|こよみ}の{上|うえ}では{春|はる}（　　）、まだ{毎日|まいにち}{寒|さむ}い{日|ひ}が{続|つづ}いている。","options":["だけに","となると","につき","とはいうものの"],"answer":3,"vi":"Theo lịch thì đã là mùa xuân, nhưng ngày nào trời cũng vẫn lạnh.","explain":"N＋とはいうものの: nói là vậy nhưng thực tế khác. だけに (chính vì… nên càng), となると (hễ đến), につき (vì - thông báo) không hợp."}],
  "14.2": [{"q":"{狭|せま}い（　　）、{駅|えき}に{近|ちか}くて{便利|べんり}な{部屋|へや}だ。","options":["ばかりに","ながらも","からといって","だけに"],"answer":1,"vi":"Tuy hẹp nhưng là căn phòng gần ga, tiện lợi.","explain":"Aい＋ながらも: tuy… nhưng. ばかりに (chỉ vì… mà kết quả xấu) và だけに (chính vì… nên càng) không phù hợp quan hệ trái ngược."},{"q":"{彼女|かのじょ}は{子|こ}ども（　　）、{大人|おとな}も{驚|おどろ}くほどしっかりした{意見|いけん}を{言|い}う。","options":["どころか","ながら","として","だけに"],"answer":1,"vi":"Tuy chỉ là trẻ con nhưng cô bé nói ra ý kiến chững chạc đến mức người lớn cũng ngạc nhiên.","explain":"N＋ながら: tuy là… nhưng. どころか (đừng nói…), として (với tư cách), だけに (chính vì) không thể hiện ý trái ngược."}],
  "14.3": [{"q":"{早|はや}く{寝|ね}なければと{思|おも}い（　　）、つい{夜中|よなか}までスマホを{見|み}てしまう。","options":["{次第|しだい}","つつある","つつも","きれず"],"answer":2,"vi":"Dù nghĩ là phải ngủ sớm nhưng tôi vẫn lỡ xem điện thoại đến nửa đêm.","explain":"Vます＋つつも: dù biết/nghĩ vậy nhưng vẫn làm. つつある là 'đang dần', 次第 là 'ngay khi', không hợp."},{"q":"{彼|かれ}は{上司|じょうし}に{不満|ふまん}を{感|かん}じ（　　）、{何|なに}も{言|い}えずにいる。","options":["つつある","つつも","{次第|しだい}","かねない"],"answer":1,"vi":"Dù cảm thấy bất mãn với cấp trên nhưng anh ấy vẫn không nói được gì.","explain":"つつも diễn tả hai việc trái ngược nhau. つつある (đang dần), かねない (có thể xảy ra điều xấu), 次第 (ngay khi) đều sai."}],
  "14.4": [{"q":"{海外|かいがい}{旅行|りょこう}（　　）、{隣|となり}の{国|くに}に{二日|ふつか}{行|い}っただけです。","options":["といっても","からといって","にしても","となると"],"answer":0,"vi":"Nói là du lịch nước ngoài nhưng thực ra chỉ đi nước láng giềng có hai ngày.","explain":"といっても: nói là vậy nhưng thực tế mức độ thấp hơn. からといって (chỉ vì) và となると (hễ đến) không hợp."},{"q":"{社長|しゃちょう}（　　）、{社員|しゃいん}が{三人|さんにん}しかいない{小|ちい}さな{会社|かいしゃ}です。","options":["だけあって","といえば","とは","といっても"],"answer":3,"vi":"Nói là giám đốc nhưng chỉ là công ty nhỏ có ba nhân viên thôi.","explain":"といっても điều chỉnh ấn tượng của từ 社長. だけあって là 'quả xứng danh', といえば là liên tưởng, とは là định nghĩa."}],
  "14.5": [{"q":"{外国|がいこく}に{住|す}んでいる（　　）、その{国|くに}の{言葉|ことば}が{話|はな}せるとは{限|かぎ}らない。","options":["ものの","からといって","からには","だけに"],"answer":1,"vi":"Chỉ vì sống ở nước ngoài không có nghĩa là nói được ngôn ngữ của nước đó.","explain":"からといって…とは限らない: chỉ vì lý do đó thì chưa chắc. からには (một khi đã thì phải), だけに (chính vì… nên càng) không hợp."},{"q":"{少|すこ}し{熱|ねつ}が{下|さ}がった（　　）、すぐに{無理|むり}をしてはいけない。","options":["からには","おかげで","だけに","からといって"],"answer":3,"vi":"Chỉ vì sốt hạ một chút mà làm quá sức ngay thì không được.","explain":"からといって + phủ định/cấm đoán: không nên chỉ vì lý do đó. おかげで là 'nhờ', からには là 'một khi đã… thì phải'."}],
  "15.0": [{"q":"もし{宝|たから}くじで{一億円|いちおくえん}{当|あ}たった（　　）、{何|なに}に{使|つか}いますか。","options":["としたら","としても","からといって","ものなら"],"answer":0,"vi":"Nếu giả sử trúng xổ số một trăm triệu yên, bạn sẽ dùng vào việc gì?","explain":"もし～としたら: giả định. としても là 'cho dù', ものなら là 'nếu có thể', không hợp với câu hỏi giả định."},{"q":"{明日|あした}{引|ひ}っ{越|こ}す（　　）、{今日中|きょうじゅう}に{荷造|にづく}りを{終|お}えなければならない。","options":["としても","となれば","ものの","にしろ"],"answer":1,"vi":"Nếu mà mai chuyển nhà thì phải đóng gói xong trong hôm nay.","explain":"となれば: nếu tình huống đó xảy ra thì (đương nhiên phải…). としても/にしろ là 'cho dù', ものの là 'tuy… nhưng'."}],
  "15.1": [{"q":"{戻|もど}れる（　　）、{学生|がくせい}{時代|じだい}に{戻|もど}りたい。","options":["ものなら","ものの","ものか","もので"],"answer":0,"vi":"Nếu có thể quay lại thì tôi muốn quay lại thời sinh viên.","explain":"Thể khả năng＋ものなら～たい: nếu có thể (dù khó) thì muốn. ものの là 'tuy', ものか là phủ định mạnh, もので là lý do."},{"q":"{代|か}われる（　　）{代|か}わってあげたいが、この{痛|いた}みは{本人|ほんにん}にしかわからない。","options":["ものか","もので","ものの","ものなら"],"answer":3,"vi":"Nếu có thể thay được thì tôi muốn chịu thay, nhưng nỗi đau này chỉ người trong cuộc mới hiểu.","explain":"ものなら + nguyện vọng khó thực hiện. もので (vì), ものの (tuy), ものか (làm sao mà) không hợp."}],
  "15.2": [{"q":"{部長|ぶちょう}に{少|すこ}しでも{反論|はんろん}し（　　）、{大声|おおごえ}で{怒鳴|どな}られる。","options":["たものの","ようものなら","てからでないと","つつ"],"answer":1,"vi":"Hễ mà cãi lại trưởng phòng dù chỉ một chút thôi là sẽ bị quát ầm lên.","explain":"Vよう＋ものなら: nếu lỡ làm vậy thì hậu quả nghiêm trọng. たものの là 'tuy đã', てからでないと là 'nếu chưa… thì không', つつ là 'vừa/dù'."},{"q":"うちの{猫|ねこ}は、{知|し}らない{人|ひと}が{触|さわ}ろう（　　）、すぐにひっかく。","options":["ものの","ものか","ものなら","もので"],"answer":2,"vi":"Con mèo nhà tôi, hễ người lạ định chạm vào là nó cào ngay.","explain":"触ろうものなら: nếu lỡ… thì kết quả xấu. ものの (tuy), ものか (phủ định mạnh), もので (lý do) không đi với thể ý chí như vậy."}],
  "15.3": [{"q":"{実際|じっさい}に{使|つか}ってみ（　　）、この{機械|きかい}が{便利|べんり}かどうかわからない。","options":["ないくせに","ないものか","ないようで","ないことには"],"answer":3,"vi":"Nếu không thực sự dùng thử thì không biết cái máy này có tiện hay không.","explain":"～ないことには～ない: nếu không làm A thì không thể B. ないくせに (vậy mà lại), ないものか (mong sao), ないようで (có vẻ không) đều không hợp."},{"q":"{社長|しゃちょう}の{許可|きょか}が{出|で}（　　）、この{計画|けいかく}を{進|すす}めることはできない。","options":["なくても","ないくせに","ないことには","ないものか"],"answer":2,"vi":"Nếu giám đốc chưa cho phép thì không thể tiến hành kế hoạch này.","explain":"～ないことには～ない: điều kiện bắt buộc, chưa có A thì không thể B. なくても (dù không), ないくせに (vậy mà), ないものか (mong sao) đều sai nghĩa."}],
  "15.4": [{"q":"{日本|にほん}の{戦後|せんご}の{経済|けいざい}{成長|せいちょう}は、{自動車|じどうしゃ}{産業|さんぎょう}（　　）{語|かた}れない。","options":["を{抜|ぬ}きにしては","を{問|と}わず","にかかわらず","はさておき"],"answer":0,"vi":"Sự tăng trưởng kinh tế thời hậu chiến của Nhật không thể nói đến nếu bỏ qua ngành ô tô.","explain":"～を抜きにしては～ない: nếu không có/bỏ qua A thì không thể. はさておき là gác lại, mâu thuẫn với ý 'không thể bỏ qua'; を問わず là không phân biệt."},{"q":"{彼|かれ}の{協力|きょうりょく}（　　）、このプロジェクトの{成功|せいこう}はあり{得|え}なかった。","options":["はともかく","もかまわず","を{抜|ぬ}きにしては","を{問|と}わず"],"answer":2,"vi":"Nếu không có sự hợp tác của anh ấy thì dự án này đã không thể thành công.","explain":"を抜きにしては + あり得ない: thiếu A thì không thể. はともかく (tạm không bàn), もかまわず (bất chấp) trái nghĩa."}],
  "15.5": [{"q":"たとえ{反対|はんたい}された（　　）、{私|わたし}はこの{道|みち}を{進|すす}むつもりだ。","options":["としたら","としても","ものなら","からには"],"answer":1,"vi":"Cho dù bị phản đối, tôi vẫn định đi theo con đường này.","explain":"たとえ～としても: cho dù… thì vẫn. としたら là 'nếu giả sử thì', không đi với ý nhượng bộ; からには là 'một khi đã'."},{"q":"{冗談|じょうだん}（　　）、そんな{言|い}い{方|かた}は{失礼|しつれい}だ。","options":["につき","といえば","とは","にしても"],"answer":3,"vi":"Cho dù là đùa thì nói kiểu đó cũng là bất lịch sự.","explain":"N＋にしても: cho dù là vậy thì vẫn. につき (vì - thông báo), といえば (nhắc đến), とは (định nghĩa) không hợp."}],
  "16.0": [{"q":"インターネットの{普及|ふきゅう}（　　）、{人々|ひとびと}の{生活|せいかつ}は{大|おお}きく{変|か}わった。","options":["によって","につき","にかかわらず","のあまり"],"answer":0,"vi":"Do sự phổ biến của Internet, cuộc sống của mọi người đã thay đổi lớn.","explain":"～によって chỉ nguyên nhân dẫn đến thay đổi. につき dùng trong thông báo, のあまり là 'vì quá' (cảm xúc), にかかわらず là 'bất kể'."},{"q":"この{寺|てら}は、{地震|じしん}（　　）{被害|ひがい}を{受|う}けて、{現在|げんざい}{修理中|しゅうりちゅう}だ。","options":["につき","をめぐる","による","に{対|たい}する"],"answer":2,"vi":"Ngôi chùa này bị thiệt hại do động đất và hiện đang được tu sửa.","explain":"N＋による＋N: thiệt hại do động đất gây ra. をめぐる là 'xoay quanh', に対する là 'đối với', không chỉ nguyên nhân."}],
  "16.1": [{"q":"{道|みち}が{混|こ}んでいた（　　）、{遅|おく}れてしまって{申|もう}し{訳|わけ}ありません。","options":["ものの","ものなら","ものか","もので"],"answer":3,"vi":"Vì đường đông quá nên tôi đến muộn, thành thật xin lỗi.","explain":"～もので: nêu lý do để biện minh, xin lỗi. ものの là 'tuy', ものなら là 'nếu có thể', ものか là phủ định mạnh."},{"q":"A：どうして{電話|でんわ}に{出|で}なかったの？B：だって、{気|き}がつかなかったんだ（　　）。","options":["ものか","っけ","もの","ろう"],"answer":2,"vi":"A: Sao không nghe điện thoại vậy? B: Thì tại tớ không để ý mà.","explain":"だって～もの: biện minh trong văn nói thân mật. ものか là phủ định mạnh, っけ là hỏi lại điều quên, ろう là phỏng đoán."}],
  "16.2": [{"q":"{試験|しけん}に{合格|ごうかく}できたのは、{先生|せんせい}が{丁寧|ていねい}に{教|おし}えてくださった（　　）。","options":["せいだ","おかげだ","ばかりだ","ものだ"],"answer":1,"vi":"Tôi đỗ được kỳ thi là nhờ thầy đã tận tình chỉ dạy.","explain":"おかげだ: nhờ (kết quả tốt). せいだ dùng cho kết quả xấu, ばかりだ/ものだ không chỉ nguyên nhân."},{"q":"{寝不足|ねぶそく}の（　　）、{仕事|しごと}で{何度|なんど}もミスをしてしまった。","options":["おかげで","くせに","あまり","せいで"],"answer":3,"vi":"Tại thiếu ngủ nên tôi mắc lỗi nhiều lần trong công việc.","explain":"せいで: tại vì (kết quả xấu). おかげで dùng cho kết quả tốt, くせに là trách móc 'vậy mà', あまり đi với cảm xúc ở mức quá."}],
  "16.3": [{"q":"{彼女|かのじょ}は{緊張|きんちょう}の（　　）、スピーチの{内容|ないよう}を{全部|ぜんぶ}{忘|わす}れてしまった。","options":["おかげで","あまり","くせに","ことだから"],"answer":1,"vi":"Cô ấy vì quá căng thẳng nên quên sạch nội dung bài phát biểu.","explain":"Nの＋あまり: vì quá… nên dẫn đến kết quả bất thường. おかげで dùng cho kết quả tốt, くせに là trách móc 'vậy mà', ことだから là phán đoán dựa trên tính cách."},{"q":"{合格|ごうかく}の{知|し}らせを{聞|き}いて、{嬉|うれ}しさの（　　）{泣|な}き{出|だ}してしまった。","options":["わりに","くせに","ことだから","あまり"],"answer":3,"vi":"Nghe tin đỗ, tôi vì quá vui mừng mà bật khóc.","explain":"Nの＋あまり: vì cảm xúc quá mức nên có phản ứng bất thường (bật khóc). わりに (so với… thì), くせに (vậy mà), ことだから (vì là… nên chắc) không hợp."}],
  "16.4": [{"q":"{店内|てんない}{改装中|かいそうちゅう}（　　）、{今週|こんしゅう}いっぱい{休業|きゅうぎょう}いたします。","options":["のあまり","をめぐって","につき","にもかかわらず"],"answer":2,"vi":"Do đang sửa chữa nội thất cửa hàng, chúng tôi xin nghỉ hết tuần này.","explain":"N＋につき: vì (dùng trong thông báo, biển báo). のあまり là 'vì quá', にもかかわらず là 'mặc dù', không hợp."},{"q":"こちらは{工事中|こうじちゅう}（　　）、{立|た}ち{入|い}り{禁止|きんし}です。","options":["にもかかわらず","につき","のあまり","をめぐり"],"answer":1,"vi":"Khu vực này đang thi công nên cấm vào.","explain":"につき dùng nêu lý do trong biển báo trang trọng. にもかかわらず là 'mặc dù', をめぐり là 'xoay quanh'."}],
  "17.0": [{"q":"{雨|あめ}もやんだ（　　）、そろそろ{出|で}かけましょうか。","options":["からといって","ことだし","ものの","ばかりに"],"answer":1,"vi":"Mưa cũng đã tạnh rồi nên chúng ta đi thôi nhỉ.","explain":"～ことだし: nêu một lý do nhẹ để đề nghị. からといって (chỉ vì… mà không hẳn), ものの (tuy), ばかりに (chỉ vì - kết quả xấu) không hợp."},{"q":"みんなそろった（　　）、{会議|かいぎ}を{始|はじ}めましょう。","options":["ばかりに","ものの","からといって","ことだし"],"answer":3,"vi":"Mọi người cũng đã đủ mặt rồi nên chúng ta bắt đầu họp thôi.","explain":"ことだし + lời đề nghị ～ましょう. からといって là 'chỉ vì… mà (không hẳn)', ものの là 'tuy… nhưng'."}],
  "17.1": [{"q":"{時間|じかん}に{正確|せいかく}な{田中|たなか}さん（　　）、もうすぐ{来|く}るでしょう。","options":["にしては","のくせに","とは","のことだから"],"answer":3,"vi":"Anh Tanaka vốn đúng giờ nên chắc sắp đến thôi.","explain":"N＋のことだから: dựa vào tính cách người đó để phán đoán. にしては là 'so với', のくせに là trách móc, とは là định nghĩa/ngạc nhiên."},{"q":"いつも{明|あか}るい{彼女|かのじょ}（　　）、{新|あたら}しい{職場|しょくば}でもすぐに{友達|ともだち}ができるだろう。","options":["にしては","とは","のことだから","にかかわらず"],"answer":2,"vi":"Cô ấy lúc nào cũng vui vẻ nên chắc ở chỗ làm mới cũng sẽ có bạn ngay thôi.","explain":"のことだから + だろう: suy đoán dựa trên tính cách. にしては (so với), にかかわらず (bất kể) không hợp."}],
  "17.2": [{"q":"{期待|きたい}していた（　　）、{落|お}ちたときのショックは{大|おお}きかった。","options":["にもかかわらず","だけに","ものの","からといって"],"answer":1,"vi":"Chính vì đã kỳ vọng nhiều nên cú sốc khi trượt càng lớn.","explain":"～だけに: chính vì… nên càng…. にもかかわらず/ものの là quan hệ trái ngược, không hợp."},{"q":"このレストランは{有名|ゆうめい}な（　　）、{予約|よやく}がなかなか{取|と}れない。","options":["くせに","ものの","だけに","にもかかわらず"],"answer":2,"vi":"Nhà hàng này chính vì nổi tiếng nên rất khó đặt bàn.","explain":"Naな＋だけに: chính vì nổi tiếng nên đương nhiên khó đặt chỗ. くせに, ものの, にもかかわらず đều là quan hệ trái ngược, không hợp."}],
  "17.3": [{"q":"{一言|ひとこと}{余計|よけい}なことを{言|い}った（　　）、{彼女|かのじょ}を{怒|おこ}らせてしまった。","options":["ばかりに","だけに","からには","ものの"],"answer":0,"vi":"Chỉ vì lỡ nói một câu thừa mà làm cô ấy giận.","explain":"～ばかりに: chỉ vì một lý do nhỏ mà dẫn đến kết quả xấu (てしまった). からには là 'một khi đã', ものの là 'tuy'."},{"q":"{英語|えいご}が{話|はな}せない（　　）、{海外|かいがい}{出張|しゅっちょう}のチャンスを{逃|のが}してしまった。","options":["からには","ものの","だけあって","ばかりに"],"answer":3,"vi":"Chỉ vì không nói được tiếng Anh mà tôi đã bỏ lỡ cơ hội đi công tác nước ngoài.","explain":"ばかりに nêu nguyên nhân gây ra kết quả đáng tiếc. だけあって dùng khen ngợi xứng đáng, からには là 'một khi đã… thì phải'."}],
  "17.4": [{"q":"{約束|やくそく}した（　　）、{必|かなら}ず{守|まも}らなければならない。","options":["からには","からといって","ものの","ばかりに"],"answer":0,"vi":"Một khi đã hứa thì nhất định phải giữ lời.","explain":"～からには + なければならない: một khi đã… thì phải. からといって là 'chỉ vì… mà (không hẳn)', ものの là 'tuy'."},{"q":"こうなった（　　）、{最後|さいご}まで{戦|たたか}うしかない。","options":["{上|うえ}は","{末|すえ}に","ばかりに","ものの"],"answer":0,"vi":"Một khi sự việc đã thành ra thế này thì chỉ còn cách chiến đấu đến cùng.","explain":"Vた＋上は: đã đến nước này thì phải/chỉ còn cách. 末に là 'sau khi… cuối cùng', ばかりに là 'chỉ vì (kết quả xấu)'."}],
  "18.0": [{"q":"{彼|かれ}があんなひどいことをしたとは、{信|しん}じ（　　）。","options":["かねない","{得|え}る","つつある","がたい"],"answer":3,"vi":"Thật khó mà tin được anh ấy lại làm chuyện tồi tệ như vậy.","explain":"Vます＋がたい: khó mà (về mặt tâm lý). かねない là 'có thể xảy ra điều xấu', 得る là 'có thể', つつある là 'đang dần'."},{"q":"{子|こ}どもに{暴力|ぼうりょく}をふるうなんて、{許|ゆる}し（　　）{行為|こうい}だ。","options":["かねない","つつある","かける","がたい"],"answer":3,"vi":"Bạo hành trẻ em là hành vi khó có thể tha thứ.","explain":"許しがたい: khó lòng tha thứ. かねない (có nguy cơ), かける (làm dở), つつある (đang dần) không hợp."}],
  "18.1": [{"q":"{大切|たいせつ}な{会議|かいぎ}があるので、{熱|ねつ}があっても{休|やす}む（　　）。","options":["わけにはいかない","わけがない","ことはない","わけではない"],"answer":0,"vi":"Vì có cuộc họp quan trọng nên dù sốt tôi cũng không thể nghỉ được.","explain":"～わけにはいかない: vì lý do trách nhiệm/hoàn cảnh nên không thể làm. ことはない là 'không cần', わけではない là 'không hẳn là'."},{"q":"{先輩|せんぱい}にごちそうしてもらったが、{毎回|まいかい}そうしてもらう（　　）、{今日|きょう}は{私|わたし}が{払|はら}った。","options":["わけがなく","ことはなく","わけにもいかず","どころではなく"],"answer":2,"vi":"Được đàn anh khao rồi, nhưng không thể lần nào cũng để anh ấy trả nên hôm nay tôi đã trả.","explain":"わけにもいかず: xét về lẽ thường thì cũng không thể làm vậy. わけがなく (không thể có chuyện), どころではなく (không phải lúc) không hợp."}],
  "18.2": [{"q":"{申|もう}し{訳|わけ}ございませんが、そのご{要望|ようぼう}にはお{応|こた}えし（　　）。","options":["かねません","かねます","{得|え}ます","つつあります"],"answer":1,"vi":"Thành thật xin lỗi, nhưng chúng tôi khó có thể đáp ứng yêu cầu đó.","explain":"Vます＋かねます: từ chối lịch sự. かねません nghĩa ngược là 'có thể xảy ra (điều xấu)', 得ます là 'có thể'."},{"q":"この{件|けん}については、{私|わたし}{一人|ひとり}では{判断|はんだん}し（　　）ので、{上司|じょうし}に{相談|そうだん}します。","options":["かねない","つつある","かねる","{得|え}る"],"answer":2,"vi":"Về việc này, một mình tôi khó có thể quyết định nên tôi sẽ trao đổi với cấp trên.","explain":"判断しかねる: khó có thể quyết định. かねない là 'có nguy cơ', 得る là 'có thể' — mâu thuẫn với việc phải hỏi cấp trên."}],
  "18.3": [{"q":"{連絡先|れんらくさき}がわからないので、{知|し}らせ（　　）。","options":["ようがない","かねない","がたい","つつある"],"answer":0,"vi":"Vì không biết thông tin liên lạc nên không có cách nào để báo cho họ.","explain":"Vます＋ようがない: không có phương tiện/cách để làm. がたい là khó về mặt tâm lý, かねない là 'có nguy cơ'."},{"q":"こんなに{壊|こわ}れてしまっては、もう{直|なお}し（　　）。","options":["かねない","{得|う}る","ようがない","つつある"],"answer":2,"vi":"Hỏng đến mức này thì không còn cách nào sửa được nữa.","explain":"直しようがない: không còn cách nào sửa. かねない (có nguy cơ), 得る (có thể) trái nghĩa, つつある (đang dần) không hợp."}],
  "18.4": [{"q":"{引|ひ}っ{越|こ}しの{準備|じゅんび}で{忙|いそが}しくて、{花見|はなみ}（　　）。","options":["にすぎない","どころではない","に{違|ちが}いない","というものだ"],"answer":1,"vi":"Bận chuẩn bị chuyển nhà nên chẳng phải lúc đi ngắm hoa.","explain":"N＋どころではない: hoàn cảnh không cho phép. にすぎない (chỉ là), に違いない (chắc chắn), というものだ (đó mới là) không hợp."},{"q":"{頭痛|ずつう}がひどくて、{勉強|べんきょう}（　　）。","options":["に{違|ちが}いない","にすぎない","どころではない","というものだ"],"answer":2,"vi":"Đau đầu dữ dội nên chẳng thể học hành gì được.","explain":"どころではない: không ở trạng thái có thể làm việc đó. に違いない (chắc chắn), にすぎない (chỉ là), というものだ (đó mới là) không hợp."}],
  "18.5": [{"q":"どんなに{注意|ちゅうい}していても、{事故|じこ}は{起|お}こり（　　）。","options":["{得|う}る","がたい","かねる","ようがない"],"answer":0,"vi":"Dù cẩn thận đến đâu thì tai nạn vẫn có thể xảy ra.","explain":"Vます＋得る: có khả năng xảy ra. がたい (khó mà), かねる (khó có thể làm - từ chối) mâu thuẫn với どんなに～ても."},{"q":"{彼|かれ}が{犯人|はんにん}だなんて、そんなことはあり（　　）。","options":["かねる","{得|え}ない","つつある","がたい"],"answer":1,"vi":"Anh ấy là thủ phạm ư, chuyện đó không thể nào có được.","explain":"あり得ない: không thể có. ありがたい nghĩa là 'biết ơn', かねる/つつある không hợp với ある."}],
  "19.0": [{"q":"この{店|みせ}の{料理|りょうり}は{値段|ねだん}が{高|たか}い（　　）、{味|あじ}はたいしたことがない。","options":["わりに","だけあって","からこそ","ばかりに"],"answer":0,"vi":"Món ăn ở quán này so với giá đắt thì vị lại chẳng có gì đặc biệt.","explain":"わりに: kết quả không tương xứng với mức độ (giá cao) đã dự đoán. だけあって/からこそ chỉ kết quả tương xứng, trái nghĩa với vế sau."},{"q":"{父|ちち}はあまり{練習|れんしゅう}していない（　　）、ゴルフが{上手|じょうず}だ。","options":["だけあって","ばかりに","わりに","ために"],"answer":2,"vi":"Bố tôi so với việc không luyện tập mấy thì chơi golf lại giỏi.","explain":"わりに diễn tả kết quả trái với mức độ dự đoán (ít tập mà giỏi). だけあって dùng khi kết quả đúng như kỳ vọng; ばかりに/ために chỉ nguyên nhân."}],
  "19.1": [{"q":"{初|はじ}めて{作|つく}った（　　）、このケーキはとてもよくできている。","options":["だけあって","にしては","あげく","{末|すえ}に"],"answer":1,"vi":"Tuy là lần đầu làm nhưng chiếc bánh này rất ngon/đẹp.","explain":"にしては: so với sự thật 'lần đầu làm' thì kết quả khác dự đoán. だけあって là đúng như kỳ vọng; あげく/末に cần quá trình dài."},{"q":"{十月|じゅうがつ}（　　）、{今日|きょう}は{夏|なつ}のように{暑|あつ}い。","options":["として","にとって","にかけては","にしては"],"answer":3,"vi":"Tuy là tháng Mười nhưng hôm nay nóng như mùa hè.","explain":"にしては đi với từ không chỉ mức độ (tháng Mười) và vế sau khác dự đoán. として (tư cách), にとって (đối với ai) không hợp nghĩa."}],
  "19.2": [{"q":"{彼|かれ}の{英語|えいご}は{本当|ほんとう}に{自然|しぜん}だ。さすが{十年|じゅうねん}もアメリカに{住|す}んでいた（　　）。","options":["にすぎない","わけがない","だけのことはある","おそれがある"],"answer":2,"vi":"Tiếng Anh của anh ấy thật tự nhiên. Quả đúng là đã sống ở Mỹ tới mười năm.","explain":"だけのことはある: kết quả xứng đáng với điều kiện (sống ở Mỹ lâu), hay đi với さすが. にすぎない hạ thấp, わけがない phủ định, không hợp."},{"q":"この{店|みせ}のラーメンは{本当|ほんとう}においしい。{一時間|いちじかん}も{並|なら}んだ（　　）。","options":["だけのことはある","にすぎない","わけではない","ところだった"],"answer":0,"vi":"Mì ramen quán này thật ngon. Thảo nào đáng công xếp hàng cả tiếng.","explain":"だけのことはある đánh giá cao, xứng với công sức bỏ ra. ところだった là 'suýt nữa', にすぎない là 'chỉ là', đều không hợp."}],
  "19.3": [{"q":"{彼女|かのじょ}は{通訳|つうやく}（　　）{国際会議|こくさいかいぎ}に{参加|さんか}した。","options":["にしたら","にとって","にしては","として"],"answer":3,"vi":"Cô ấy đã tham gia hội nghị quốc tế với tư cách là phiên dịch viên.","explain":"として chỉ tư cách, vai trò, vế sau là hành động. にとって/にしたら dùng cho quan điểm đánh giá, không đi với hành động; にしては là 'tuy là… nhưng'."},{"q":"{親|おや}（　　）、{子供|こども}の{安全|あんぜん}を{守|まも}るのは{当然|とうぜん}の{責任|せきにん}だ。","options":["にしては","として","だけあって","わりに"],"answer":1,"vi":"Với tư cách là cha mẹ, bảo vệ sự an toàn của con cái là trách nhiệm đương nhiên.","explain":"として nêu lập trường, vai trò 'cha mẹ'. にしては/わりに diễn tả sự trái với dự đoán, だけあって là 'quả đúng là', không hợp."}],
  "19.4": [{"q":"{外国人|がいこくじん}（　　）、{日本語|にほんご}の{敬語|けいご}はとても{難|むずか}しい。","options":["にとって","として","について","にしては"],"answer":0,"vi":"Đối với người nước ngoài, kính ngữ tiếng Nhật rất khó.","explain":"にとって + đánh giá (khó) theo quan điểm người đó. として cần vế sau là hành động/tư cách; について là 'về'; にしては là 'tuy là… nhưng'."},{"q":"この{写真|しゃしん}は{私|わたし}（　　）{何|なに}よりも{大切|たいせつ}な{宝物|たからもの}です。","options":["として","にしては","にとって","によって"],"answer":2,"vi":"Bức ảnh này đối với tôi là báu vật quý giá hơn bất cứ thứ gì.","explain":"にとって đi với danh từ chỉ người, vế sau là đánh giá (quý giá). によって là 'tùy/bởi', として là 'với tư cách', không hợp."}],
  "19.5": [{"q":"{社員|しゃいん}（　　）、{給料|きゅうりょう}が{下|さ}がるのは{困|こま}ることだろう。","options":["にかけては","にしてみれば","だけあって","にしては"],"answer":1,"vi":"Đứng ở lập trường của nhân viên thì việc lương bị giảm hẳn là điều khó khăn.","explain":"にしてみれば: đứng ở lập trường người khác để suy đoán cảm xúc (困ることだろう). にしては/だけあって là đánh giá so với dự đoán, không phải lập trường."},{"q":"{隣|となり}の{人|ひと}（　　）、{毎晩|まいばん}のピアノの{音|おと}はうるさいのかもしれない。","options":["にかけては","だけあって","にしては","にすれば"],"answer":3,"vi":"Đứng ở lập trường người hàng xóm thì tiếng piano mỗi tối có lẽ rất ồn.","explain":"にすれば suy luận cảm nhận từ lập trường của người khác (người hàng xóm). として chỉ tư cách hành động; にしては/だけあって không hợp nghĩa."}],
  "20.0": [{"q":"{駅|えき}の{近|ちか}くの{店|みせ}に{問|と}い{合|あ}わせた（　　）、もう{売|う}り{切|き}れだと{言|い}われた。","options":["あげく","きり","ところ","{末|すえ}に"],"answer":2,"vi":"Sau khi thử hỏi cửa hàng gần ga thì được báo là đã bán hết rồi.","explain":"たところ: làm thử một lần rồi nhận được kết quả. あげく/末に cần quá trình dài vất vả; きり là 'từ đó cứ thế không…'."},{"q":"{新|あたら}しい{薬|くすり}を{試|ため}してみた（　　）、{症状|しょうじょう}がすっかりよくなった。","options":["ところ","きり","あげく","ばかりに"],"answer":0,"vi":"Thử dùng loại thuốc mới thì triệu chứng đã khỏi hẳn.","explain":"たところ + kết quả phát hiện sau khi thử. あげく và ばかりに dẫn tới kết quả xấu; きり đi với trạng thái không thay đổi."}],
  "20.1": [{"q":"{兄|あに}は{三年前|さんねんまえ}に{家|いえ}を{出|で}た（　　）、{一度|いちど}も{帰|かえ}ってこない。","options":["{末|すえ}に","あげく","ところ","きり"],"answer":3,"vi":"Anh tôi rời nhà từ ba năm trước rồi cứ thế không về lần nào.","explain":"たきり: sau hành động đó, trạng thái cứ tiếp diễn, vế sau phủ định. 末に/あげく chỉ kết cục sau quá trình dài; ところ là kết quả phát hiện."},{"q":"{彼女|かのじょ}はその{本|ほん}を{借|か}りていった（　　）、まだ{返|かえ}してくれない。","options":["ところ","きり","{末|すえ}に","あげく"],"answer":1,"vi":"Cô ấy mượn cuốn sách đó đi rồi cứ thế vẫn chưa trả lại.","explain":"きり + câu phủ định diễn tả điều mong đợi mãi không xảy ra. あげく/末に cần quá trình dài; ところ không đi với trạng thái kéo dài."}],
  "20.2": [{"q":"{一時間|いちじかん}も{待|ま}たされた（　　）、{結局|けっきょく}{会議|かいぎ}は{中止|ちゅうし}になった。","options":["あげく","ばかりに","きり","ばかりか"],"answer":0,"vi":"Bị bắt chờ tới một tiếng, rốt cuộc cuộc họp lại bị hủy.","explain":"あげく: sau tình trạng không ổn kéo dài, kết quả xấu (bị hủy). きり là 'cứ thế không…', ついでに/ばかりか không hợp nghĩa."},{"q":"{彼|かれ}はさんざん{文句|もんく}を{言|い}った（　　）、{会社|かいしゃ}を{辞|や}めてしまった。","options":["きり","わりに","あげく","ところ"],"answer":2,"vi":"Anh ta phàn nàn đủ điều, rốt cuộc đã bỏ việc.","explain":"あげく đi với さんざん, kết cục không tốt (〜てしまった). ところ dùng cho kết quả phát hiện khi thử; わりに là so sánh mức độ."}],
  "20.3": [{"q":"{何度|なんど}も{話|はな}し{合|あ}った（　　）、ようやく{計画|けいかく}が{決|き}まった。","options":["あげく","{末|すえ}に","きり","ところ"],"answer":1,"vi":"Sau nhiều lần bàn bạc, cuối cùng kế hoạch cũng được quyết định.","explain":"末に: sau quá trình dài, cuối cùng đạt được kết quả/quyết định (ようやく). あげく dùng cho kết quả xấu; きり là 'cứ thế không…'."},{"q":"{十年|じゅうねん}に{及|およ}ぶ{研究|けんきゅう}の（　　）、{新|あたら}しい{薬|くすり}が{完成|かんせい}した。","options":["あげく","わりに","くせに","{末|すえ}に"],"answer":3,"vi":"Sau quá trình nghiên cứu kéo dài mười năm, cuối cùng loại thuốc mới đã hoàn thành.","explain":"Nの末に: sau quá trình dài thì có kết quả tốt. あげく chỉ kết quả xấu; わりに là so với mức độ, không hợp."}],
  "20.4": [{"q":"{寝坊|ねぼう}して、{危|あや}うく{飛行機|ひこうき}に{乗|の}り{遅|おく}れる（　　）。","options":["ものだった","わけだった","ところだった","ことだった"],"answer":2,"vi":"Tôi ngủ quên, suýt nữa thì lỡ chuyến bay.","explain":"ところだった + 危うく: suýt xảy ra điều xấu nhưng thực tế không xảy ra. ものだった là hồi tưởng; わけだった là giải thích."},{"q":"{信号|しんごう}を{見|み}ていなかったので、もう{少|すこ}しで{車|くるま}にひかれる（　　）。","options":["ところだった","ばかりだった","ものだった","ことにした"],"answer":0,"vi":"Vì không nhìn đèn tín hiệu nên tôi suýt nữa thì bị xe tông.","explain":"もう少しで〜ところだった: suýt nữa thì. ことにした là quyết định, ものだった là hồi tưởng thói quen, không hợp."}],
  "20.5": [{"q":"{京都|きょうと}に{三日|みっか}もいたのに、{忙|いそが}しくて{金閣寺|きんかくじ}には{行|い}か（　　）。","options":["ずにはいられなかった","ざるを{得|え}なかった","ずにすんだ","ずじまいだった"],"answer":3,"vi":"Ở Kyoto tới ba ngày mà vì bận nên rốt cuộc không đi được chùa Kinkakuji.","explain":"ずじまいだった: định làm mà rốt cuộc không làm được, mang ý tiếc nuối (のに). ずにはいられない/ざるを得ない là 'không thể không/đành phải'."},{"q":"{彼女|かのじょ}に{気持|きも}ちを{伝|つた}えたかったが、{結局|けっきょく}{言|い}え（　　）。","options":["ずにはいられなかった","ずじまいだった","ざるを{得|え}なかった","ずにすんだ"],"answer":1,"vi":"Tôi muốn bày tỏ tình cảm với cô ấy nhưng rốt cuộc đã không nói ra được.","explain":"結局〜ずじまいだった: muốn làm mà cuối cùng không làm được. ずにすんだ là 'may mà không phải', ざるを得なかった là 'đành phải', không hợp."}],
  "21.0": [{"q":"{忙|いそが}しくても、{電話|でんわ}（　　）してくれてもいいのに。","options":["ぐらい","まで","ばかり","こそ"],"answer":0,"vi":"Dù bận thì ít nhất cũng có thể gọi điện cho tôi chứ.","explain":"ぐらい nêu mức tối thiểu 'ít nhất cũng…'. まで là mức cao nhất, なんか mang ý coi thường, こそ nhấn mạnh, không hợp."},{"q":"{自分|じぶん}の{部屋|へや}（　　）{自分|じぶん}で{掃除|そうじ}しなさい。","options":["まで","ばかり","ぐらい","ほど"],"answer":2,"vi":"Ít nhất phòng của mình thì tự mình dọn đi.","explain":"ぐらい: việc mức độ thấp, đương nhiên phải làm. まで là 'đến cả', ばかり là 'toàn', など mang ý coi nhẹ, không hợp."}],
  "21.1": [{"q":"あんな{嘘|うそ}つきの{言|い}うこと（　　）、{信|しん}じなくていいよ。","options":["さえ","なんか","まで","ぐらい"],"answer":1,"vi":"Mấy lời của kẻ nói dối như thế thì không cần tin đâu.","explain":"なんか thể hiện thái độ coi nhẹ, vế sau là lời khuyên. さえ/まで là 'ngay cả/đến cả', ぐらい là mức tối thiểu, không hợp."},{"q":"{私|わたし}（　　）にこんな{難|むずか}しい{仕事|しごと}ができるはずがありません。","options":["こそ","まで","ぐらい","なんか"],"answer":3,"vi":"Người như tôi thì không thể làm được công việc khó như thế này.","explain":"なんか dùng để hạ thấp (khiêm tốn) bản thân. こそ nhấn mạnh, まで là 'đến cả', ぐらい là 'ít nhất', không hợp."}],
  "21.2": [{"q":"{借金|しゃっきん}をし（　　）ブランド{品|ひん}を{買|か}う{必要|ひつよう}はないと{思|おも}う。","options":["たきり","てばかり","てまで","たところ"],"answer":2,"vi":"Tôi nghĩ không cần phải đến mức vay nợ để mua đồ hàng hiệu.","explain":"てまで: làm đến mức cực đoan, kèm thái độ phê phán (必要はない). てから là 'sau khi', ても là 'dù', không diễn tả mức độ."},{"q":"{簡単|かんたん}な{計算|けいさん}を{間違|まちが}えて、{小学生|しょうがくせい}の{弟|おとうと}に（　　）{笑|わら}われた。","options":["まで","こそ","しか","ほど"],"answer":0,"vi":"Tính sai một phép tính đơn giản, đến cả đứa em tiểu học cũng cười tôi.","explain":"まで: đến cả (mức cao nhất, bất ngờ). しか cần phủ định, こそ là nhấn mạnh, ほど là so sánh mức độ, không hợp."}],
  "21.3": [{"q":"その{事故|じこ}で、{乗客|じょうきゃく}は{一人|ひとり}（　　）けがをしなかった。","options":["さえ","まで","ぐらい","として"],"answer":3,"vi":"Trong vụ tai nạn đó, không một hành khách nào bị thương.","explain":"一人として〜ない: không một ai. まで/ぐらい không đi với 一人 + phủ định theo nghĩa này; さえ là 'ngay cả'."},{"q":"{彼|かれ}の{話|はなし}には{何一|なにひと}つ（　　）{本当|ほんとう}のことがなかった。","options":["にとって","として","にしては","なんて"],"answer":1,"vi":"Trong câu chuyện của anh ta không có một điều nào là sự thật.","explain":"何一つとして〜ない: phủ định hoàn toàn. にとって/にしては không đi sau từ chỉ số lượng; なんて là coi nhẹ."}],
  "21.4": [{"q":"{忙|いそが}しくて、{昼|ひる}ご{飯|はん}を{食|た}べる{時間|じかん}（　　）なかった。","options":["さえ","こそ","ばかり","ほど"],"answer":0,"vi":"Bận đến mức ngay cả thời gian ăn trưa cũng không có.","explain":"さえ: đưa ra ví dụ mức thấp nhất, những thứ khác là đương nhiên. こそ nhấn mạnh khẳng định, ばかり là 'toàn', ほど là so sánh."},{"q":"{天気|てんき}（　　）よければ、{明日|あした}は{富士山|ふじさん}がきれいに{見|み}えるはずだ。","options":["まで","こそ","さえ","なんか"],"answer":2,"vi":"Chỉ cần thời tiết đẹp là ngày mai chắc chắn sẽ nhìn thấy núi Phú Sĩ rõ.","explain":"さえ〜ば: chỉ cần một điều kiện là đủ. まで/こそ/なんか không đi với 〜ば để diễn tả điều kiện đủ."}],
  "21.5": [{"q":"{会社|かいしゃ}を{休|やす}ん（　　）、{明日|あした}の{決勝戦|けっしょうせん}は{絶対|ぜったい}に{見|み}に{行|い}きたい。","options":["だきり","でも","だところ","だあげく"],"answer":1,"vi":"Dù có phải nghỉ làm thì tôi cũng nhất định muốn đi xem trận chung kết ngày mai.","explain":"てでも + ý chí, nguyện vọng (絶対に行きたい): dù phải dùng cách bình thường không làm. たきり/たところ/たあげく chỉ kết quả trong quá khứ, không đi với nguyện vọng."},{"q":"{徹夜|てつや}し（　　）、この{仕事|しごと}は{明日|あした}までに{終|お}わらせなければならない。","options":["たあげく","たきり","たところ","てでも"],"answer":3,"vi":"Dù có phải thức trắng đêm thì việc này cũng phải xong trước ngày mai.","explain":"てでも: dù phải làm điều bình thường không làm, vế sau là ý chí/nghĩa vụ. たきり/たところ/たあげく là kết quả trong quá khứ, không hợp với vế sau."}],
  "22.0": [{"q":"{部屋|へや}の{電気|でんき}が{消|き}えている。{隣|となり}の{人|ひと}は{出|で}かけている（　　）。","options":["にすぎない","ものか","とみえる","ことだ"],"answer":2,"vi":"Đèn trong phòng đã tắt. Có vẻ như người hàng xóm đang ra ngoài.","explain":"とみえる: suy đoán dựa trên chứng cứ nhìn thấy (đèn tắt). にすぎない là 'chỉ là', ものか là phủ định mạnh, ことだ là lời khuyên."},{"q":"{彼|かれ}は{朝|あさ}からずっとにこにこしている。{何|なに}かいいことがあった（　　）。","options":["とみえる","べきだ","ものがある","ことはない"],"answer":0,"vi":"Anh ấy cứ tươi cười từ sáng. Có vẻ như đã có chuyện gì vui.","explain":"とみえる suy đoán từ trạng thái của người khác (にこにこしている). ことはない/べきだ là khuyên nhủ, ものがある là cảm thán."}],
  "22.1": [{"q":"そんなにスピードを{出|だ}したら、{事故|じこ}を{起|お}こし（　　）よ。","options":["かねる","がたい","っこない","かねない"],"answer":3,"vi":"Chạy nhanh như thế thì có thể gây tai nạn đấy.","explain":"かねない: có khả năng xảy ra kết quả xấu. かねる là 'khó có thể (làm)', がたい là 'khó mà', っこない là 'không đời nào', ngược nghĩa."},{"q":"{彼|かれ}の{性格|せいかく}なら、{上司|じょうし}にも{失礼|しつれい}なことを{言|い}い（　　）。","options":["かねる","かねない","ようがない","っこない"],"answer":1,"vi":"Với tính cách của anh ta thì có khi còn nói điều thất lễ với cả cấp trên.","explain":"かねない: suy từ tính cách hiện tại, có thể xảy ra điều xấu. かねる/ようがない/っこない đều mang nghĩa không thể, trái ngữ cảnh."}],
  "22.2": [{"q":"{明日|あした}は{大雨|おおあめ}で{川|かわ}が{氾濫|はんらん}する（　　）ので、{注意|ちゅうい}してください。","options":["おそれがある","ものがある","ことはない","にすぎない"],"answer":0,"vi":"Ngày mai có nguy cơ sông bị tràn do mưa lớn nên xin hãy chú ý.","explain":"おそれがある: có nguy cơ xảy ra việc xấu, hay dùng trong thông báo, tin tức. ことはない mâu thuẫn với 注意してください."},{"q":"この{薬|くすり}は{副作用|ふくさよう}の（　　）ので、{医師|いし}の{指示|しじ}に{従|したが}って{飲|の}んでください。","options":["はずがない","わけがない","おそれがある","おそれはない"],"answer":2,"vi":"Thuốc này có nguy cơ gây tác dụng phụ nên hãy uống theo chỉ dẫn của bác sĩ.","explain":"Nのおそれがある: có nguy cơ. はずがない/わけがない/おそれはない đều phủ định khả năng, không phải lý do để dặn uống theo chỉ dẫn bác sĩ."}],
  "22.3": [{"q":"{机|つくえ}の{上|うえ}に{彼|かれ}のかばんがある。まだ{会社|かいしゃ}にいる（　　）。","options":["にすぎない","に{違|ちが}いない","ものか","ことはない"],"answer":1,"vi":"Cặp của anh ấy vẫn ở trên bàn. Chắc chắn anh ấy vẫn còn ở công ty.","explain":"に違いない: phán đoán chắc chắn dựa vào chứng cứ (cái cặp). にすぎない là 'chỉ là', ものか/ことはない không phải phán đoán."},{"q":"{現場|げんば}に{残|のこ}された{指紋|しもん}から{考|かんが}えると、{犯人|はんにん}はこの{男|おとこ}（　　）。","options":["にすぎない","というものだ","に{越|こ}したことはない","に{違|ちが}いない"],"answer":3,"vi":"Xét từ dấu vân tay để lại ở hiện trường thì thủ phạm chắc chắn là người đàn ông này.","explain":"に違いない: kết luận chắc chắn dựa trên chứng cứ (指紋から考えると). というものだ là đánh giá theo lẽ thường, に越したことはない là 'tốt nhất là'."}],
  "22.4": [{"q":"こんな{寒|さむ}い{日|ひ}に{薄着|うすぎ}で{出|で}かけたら、{風邪|かぜ}をひく（　　）じゃないか。","options":["にすぎない","ことはない","にきまっている","わけがない"],"answer":2,"vi":"Ngày lạnh thế này mà mặc phong phanh ra ngoài thì nhất định là bị cảm rồi còn gì.","explain":"にきまっている: phán đoán chủ quan chắc chắn, ai cũng nghĩ vậy. わけがない/ことはない phủ định, trái logic; にすぎない là 'chỉ là'."},{"q":"{子供|こども}に「{勉強|べんきょう}と{遊|あそ}び、どっちが{好|す}き？」と{聞|き}いたら、{遊|あそ}びと{答|こた}える（　　）。","options":["にきまっている","ことはない","ものがある","にすぎない"],"answer":0,"vi":"Nếu hỏi trẻ con 'Học và chơi, con thích cái nào?' thì nhất định chúng sẽ trả lời là chơi.","explain":"にきまっている: nhận định chủ quan, hiển nhiên. にすぎない là 'chỉ là', ことはない là 'không cần', ものがある là cảm thán."}],
  "22.5": [{"q":"{彼|かれ}は{一度|いちど}{断|ことわ}られたのだから、もう{二度|にど}と{来|く}る（　　）。","options":["べきだ","ことだ","ものだ","まい"],"answer":3,"vi":"Anh ta đã bị từ chối một lần rồi nên chắc là sẽ không bao giờ đến nữa.","explain":"まい: phán đoán phủ định 'chắc là không', hợp với 二度と. べきだ/ことだ/ものだ là khuyên nhủ, lẽ thường, mâu thuẫn với 二度と."},{"q":"{彼|かれ}の{説明|せつめい}には{矛盾|むじゅん}が{多|おお}い。{何|なに}か{隠|かく}している（　　）。","options":["ものか","のではあるまいか","ことはない","べきではない"],"answer":1,"vi":"Lời giải thích của anh ta có nhiều mâu thuẫn. Chẳng phải là anh ta đang che giấu điều gì sao?","explain":"のではあるまいか: phán đoán chủ quan 'chẳng phải là… sao'. ものか phủ định mạnh, trái với 矛盾が多い; ことはない/べきではない là khuyên nhủ, không phải suy đoán."}],
  "23.0": [{"q":"{人|ひと}は{誰|だれ}でも、{褒|ほ}められると{嬉|うれ}しくなる（　　）。","options":["ものだ","ことだ","ところだった","にすぎない"],"answer":0,"vi":"Con người ai cũng vậy, được khen thì sẽ vui.","explain":"ものだ: nêu lẽ thường, bản chất chung của con người. ことだ là lời khuyên cụ thể; ところだった là 'suýt nữa'."},{"q":"{年|とし}を{取|と}ると、{時間|じかん}が{経|た}つのが{速|はや}く{感|かん}じられる（　　）。","options":["ことだ","べきだ","ものだ","ことはない"],"answer":2,"vi":"Khi có tuổi thì người ta thường cảm thấy thời gian trôi nhanh.","explain":"ものだ diễn tả lẽ thường chung. べきだ/ことだ là khuyên nhủ, ことはない là 'không cần', không hợp với cảm giác tự nhiên."}],
  "23.1": [{"q":"{自分|じぶん}のミスを{部下|ぶか}のせいにするなんて、{無責任|むせきにん}（　　）。","options":["にすぎない","というものだ","に{越|こ}したことはない","でならない"],"answer":1,"vi":"Đổ lỗi của mình cho cấp dưới thì đúng là vô trách nhiệm.","explain":"というものだ: dùng lẽ thường đánh giá một việc cụ thể. にすぎない là 'chỉ là', に越したことはない là 'tốt nhất', でならない là cảm xúc người nói."},{"q":"{困|こま}っている{人|ひと}を{助|たす}けるのが{本当|ほんとう}の{友情|ゆうじょう}（　　）。","options":["にすぎない","だけのことはある","に{越|こ}したことはない","というものだ"],"answer":3,"vi":"Giúp đỡ người đang gặp khó khăn, thế mới là tình bạn thật sự.","explain":"というものだ: 'thế mới đúng là…' theo lẽ thường. にすぎない hạ thấp, だけのことはある cần điều kiện đi trước, không hợp."}],
  "23.2": [{"q":"{社長|しゃちょう}といっても、{社員|しゃいん}{三人|さんにん}の{小|ちい}さな{会社|かいしゃ}の{社長|しゃちょう}（　　）。","options":["にほかならない","というものだ","にすぎない","に{越|こ}したことはない"],"answer":2,"vi":"Nói là giám đốc nhưng chỉ là giám đốc một công ty nhỏ có ba nhân viên.","explain":"にすぎない: chỉ là, không có gì đặc biệt (といっても). にほかならない là 'chính là' (nhấn mạnh), ngược sắc thái."},{"q":"これは{私|わたし}の{個人的|こじんてき}な{意見|いけん}（　　）ので、{参考|さんこう}{程度|ていど}に{聞|き}いてください。","options":["にすぎない","にきまっている","に{越|こ}したことはない","にほかならない"],"answer":0,"vi":"Đây chỉ là ý kiến cá nhân của tôi nên xin hãy nghe để tham khảo thôi.","explain":"にすぎない: chỉ là, không quan trọng (参考程度). にほかならない/にきまっている mang ý khẳng định mạnh, trái ngữ cảnh."}],
  "23.3": [{"q":"{彼|かれ}が{成功|せいこう}したのは、{毎日|まいにち}の{努力|どりょく}の{結果|けっか}（　　）。","options":["に{越|こ}したことはない","だけのことはある","でしょうがない","にほかならない"],"answer":3,"vi":"Việc anh ấy thành công không gì khác chính là kết quả của sự nỗ lực mỗi ngày.","explain":"にほかならない: kết luận 'chính là, không gì khác'. に越したことはない là 'tốt nhất là', だけのことはある là 'quả đúng là', でしょうがない là cảm xúc, không hợp."},{"q":"{子供|こども}を{厳|きび}しく{叱|しか}るのも、{親|おや}の{愛情|あいじょう}（　　）。","options":["に{越|こ}したことはない","にほかならない","だけのことはある","でしょうがない"],"answer":1,"vi":"Việc mắng con nghiêm khắc cũng chính là tình yêu thương của cha mẹ.","explain":"にほかならない: khẳng định 'chính là, không gì khác'. に越したことはない là 'tốt nhất là', だけのことはある là 'quả đúng là', でしょうがない chỉ cảm xúc, đều không hợp."}],
  "23.4": [{"q":"{旅行|りょこう}の{荷物|にもつ}は{軽|かる}い（　　）。","options":["に{越|こ}したことはない","ことはない","ものがある","にすぎない"],"answer":0,"vi":"Hành lý đi du lịch thì nhẹ là tốt nhất.","explain":"に越したことはない: không bắt buộc nhưng nếu được vậy thì tốt nhất. にすぎない là 'chỉ là', ものがある là cảm thán, không hợp."},{"q":"{大丈夫|だいじょうぶ}だとは{思|おも}うが、{念|ねん}のため{確認|かくにん}しておく（　　）。","options":["ことはない","にすぎない","に{越|こ}したことはない","ものか"],"answer":2,"vi":"Tôi nghĩ là ổn nhưng để cho chắc thì kiểm tra trước vẫn là tốt nhất.","explain":"に越したことはない hợp với 念のため (không bắt buộc nhưng nên). ことはない (không cần) và ものか (đời nào) mâu thuẫn với 念のため."}],
  "23.5": [{"q":"{終電|しゅうでん}に{乗|の}り{遅|おく}れたから、タクシーで{帰|かえ}る（　　）。","options":["ことはない","しかない","ものか","わけがない"],"answer":1,"vi":"Vì lỡ chuyến tàu cuối nên chỉ còn cách về bằng taxi.","explain":"しかない: không còn lựa chọn nào khác. ことはない (không cần), ものか (đời nào), わけがない (không thể nào) đều trái tình huống."},{"q":"{誰|だれ}も{手伝|てつだ}ってくれないなら、{自分|じぶん}{一人|ひとり}でやる（　　）。","options":["ものがある","ことはない","べきではない","よりほかない"],"answer":3,"vi":"Nếu không ai giúp thì đành phải tự mình làm thôi.","explain":"よりほかない: không còn cách nào khác, đành phải. ことはない/べきではない phủ định, ものがある là cảm thán, không hợp."}],
  "23.6": [{"q":"{約束|やくそく}した{以上|いじょう}、{最後|さいご}まで{責任|せきにん}を{持|も}つ（　　）。","options":["ことはない","にすぎない","べきだ","ところだった"],"answer":2,"vi":"Một khi đã hứa thì nên chịu trách nhiệm đến cùng.","explain":"以上〜べきだ: đương nhiên nên làm. ことはない là 'không cần', にすぎない là 'chỉ là', ところだった là 'suýt'."},{"q":"{人|ひと}の{秘密|ひみつ}を{勝手|かって}に{他|ほか}の{人|ひと}に{話|はな}す（　　）。","options":["べきではない","ところだった","に{越|こ}したことはない","しかない"],"answer":0,"vi":"Không nên tự tiện kể bí mật của người khác cho người khác nghe.","explain":"べきではない: ý kiến người nói rằng không nên làm. しかない (đành phải) và に越したことはない (tốt nhất là) trái đạo lý trong câu."}],
  "24.0": [{"q":"{地域|ちいき}の{皆|みな}さん、{力|ちから}を{合|あ}わせてこの{町|まち}を（　　）。","options":["{守|まも}るまい","{守|まも}ることはない","{守|まも}るものか","{守|まも}ろうではないか"],"answer":3,"vi":"Bà con trong vùng, chúng ta hãy cùng chung sức bảo vệ thị trấn này!","explain":"Vようではないか: lời kêu gọi mạnh mẽ trước đám đông. まい/ものか/ことはない đều mang nghĩa phủ định, trái với lời kêu gọi."},{"q":"{国民|こくみん}の{皆|みな}さん、{未来|みらい}の{子供|こども}たちのために、{今|いま}こそ{立|た}ち{上|あ}がろう（　　）。","options":["とした","ではないか","としても","ものなら"],"answer":1,"vi":"Hỡi quốc dân, vì thế hệ trẻ tương lai, chính lúc này chúng ta hãy cùng đứng lên!","explain":"ようではないか: kêu gọi số đông. ようとした là miêu tả hành động trong quá khứ, ようものなら/ようとしても là điều kiện, không phải lời kêu gọi."}],
  "24.1": [{"q":"{日本語|にほんご}が{上手|じょうず}になりたければ、{毎日|まいにち}{少|すこ}しずつでも{勉強|べんきょう}を{続|つづ}ける（　　）。","options":["ことだ","ところだ","わけだ","ばかりだ"],"answer":0,"vi":"Nếu muốn giỏi tiếng Nhật thì nên tiếp tục học mỗi ngày dù chỉ một chút.","explain":"ことだ: lời khuyên trong tình huống cụ thể (〜たければ). ところだ chỉ thời điểm, わけだ là giải thích, ばかりだ là chiều hướng xấu dần."},{"q":"{熱|ねつ}があるなら、{無理|むり}をしないで{早|はや}く{寝|ね}る（　　）よ。","options":["ところだ","ばかりだ","ことだ","はずだ"],"answer":2,"vi":"Nếu bị sốt thì đừng cố sức, nên đi ngủ sớm đi.","explain":"ことだ đưa ra lời khuyên cụ thể cho người nghe. はずだ là suy đoán, ばかりだ/ところだ không phải lời khuyên."}],
  "24.2": [{"q":"{人|ひと}の{悪口|わるぐち}を{陰|かげ}で{言|い}う（　　）。","options":["ところだった","ものではない","わけではない","しかない"],"answer":1,"vi":"Không nên nói xấu người khác sau lưng.","explain":"ものではない: theo lẽ thường thì không nên làm (nói chung cho mọi người). わけではない là phủ định một phần, ところだった là 'suýt', しかない là 'đành phải'."},{"q":"{目上|めうえ}の{人|ひと}に{会|あ}ったら、{自分|じぶん}から{挨拶|あいさつ}をする（　　）。","options":["ところだった","わけがない","ことはない","ものだ"],"answer":3,"vi":"Gặp người trên thì nên tự mình chào trước.","explain":"ものだ: nên làm theo lẽ thường, phép tắc xã hội. ことはない (không cần) và わけがない (không thể nào) ngược nghĩa."}],
  "24.3": [{"q":"{小|ちい}さなミスだから、そんなに{落|お}ち{込|こ}む（　　）よ。","options":["しかない","わけがない","ことはない","ところだった"],"answer":2,"vi":"Chỉ là lỗi nhỏ nên không cần phải buồn bã như thế đâu.","explain":"ことはない: không cần thiết phải làm, dùng để an ủi. しかない là 'đành phải', わけがない là phủ định khả năng, không phải lời khuyên."},{"q":"{電話|でんわ}で{済|す}む{話|はなし}だから、わざわざ{来|く}る（　　）。","options":["ことはない","ものだ","べきだ","しかない"],"answer":0,"vi":"Chuyện có thể giải quyết qua điện thoại nên không cần phải cất công đến.","explain":"わざわざ〜ことはない: không cần mất công làm. べきだ/ものだ/しかない đều mang nghĩa nên/phải làm, trái ngữ cảnh."}],
  "24.4": [{"q":"あんなまずい{店|みせ}には{二度|にど}と{行|い}く（　　）と{思|おも}った。","options":["べきだ","ことだ","ものだ","まい"],"answer":3,"vi":"Tôi đã nghĩ sẽ không bao giờ đến cái quán dở tệ đó nữa.","explain":"二度と〜まい: quyết không làm. べきだ/ことだ/ものだ là nên làm, mâu thuẫn với 二度と và まずい."},{"q":"パーティーに{行|い}こうか{行|い}く（　　）か、まだ{迷|まよ}っている。","options":["べき","まい","もの","はず"],"answer":1,"vi":"Tôi vẫn đang phân vân nên đi dự tiệc hay không.","explain":"Vようか〜まいか: phân vân làm hay không làm. べき/もの/はず không tạo cặp đối lập với 行こうか."}],
  "24.5": [{"q":"あんなに{失礼|しつれい}なことを{言|い}われたんだ。{絶対|ぜったい}に{許|ゆる}す（　　）。","options":["ものか","ことだ","ものだ","わけだ"],"answer":0,"vi":"Bị nói những lời vô lễ như thế. Đời nào tôi tha thứ.","explain":"ものか: phủ định mạnh, cảm tính 'nhất định không'. ものだ/ことだ là lẽ thường/lời khuyên, わけだ là giải thích, trái ý giận dữ."},{"q":"{誰|だれ}がこんな{高|たか}い{店|みせ}でまた{食事|しょくじ}をする（　　）。","options":["ことだ","ものだ","ものか","ところだ"],"answer":2,"vi":"Ai mà lại đi ăn ở cái quán đắt thế này lần nữa chứ.","explain":"誰が〜ものか: câu hỏi tu từ, phủ định mạnh. ことだ/ものだ/ところだ không tạo nghĩa phủ định với 誰が."}],
  "25.0": [{"q":"{昨日|きのう}からずっと{歯|は}が{痛|いた}くて（　　）。","options":["もいい","たまらない","はいけない","もかまわない"],"answer":1,"vi":"Từ hôm qua răng tôi cứ đau không chịu được.","explain":"てたまらない thường đi với cảm giác cơ thể (痛い): rất, không chịu nổi. てもいい/てはいけない/てもかまわない là cho phép/cấm đoán, không hợp nghĩa."},{"q":"{週末|しゅうまつ}の{旅行|りょこう}が{楽|たの}しみで（　　）。","options":["もいい","はいけない","もかまわない","しょうがない"],"answer":3,"vi":"Tôi mong chuyến du lịch cuối tuần quá đi mất.","explain":"Naでしょうがない: cảm xúc rất mạnh (mong chờ). でもいい/ではいけない/でもかまわない là cho phép/cấm đoán, không hợp nghĩa."}],
  "25.1": [{"q":"{一人|ひとり}で{海外|かいがい}にいる{娘|むすめ}のことが{心配|しんぱい}で（　　）。","options":["はいけない","もいい","ならない","もかまわない"],"answer":2,"vi":"Tôi lo lắng vô cùng cho con gái đang ở nước ngoài một mình.","explain":"でならない: cảm xúc (thường tiêu cực) dâng lên không kiềm được. でもいい/ではいけない/でもかまわない là cho phép/cấm đoán, không diễn tả cảm xúc."},{"q":"{何|なに}か{大切|たいせつ}なことを{忘|わす}れているような{気|き}がして（　　）。","options":["ならない","みせる","ほしい","おく"],"answer":0,"vi":"Tôi cứ thấy như mình đang quên điều gì quan trọng.","explain":"気がしてならない: cảm nghĩ tự nhiên trỗi dậy mạnh. てほしい/てみせる/ておく là hành động, mong muốn, không hợp."}],
  "25.2": [{"q":"あまりにおかしな{話|はなし}だったので、{笑|わら}わ（　　）。","options":["ずじまいだった","ずにおいた","ずにすんだ","ずにはいられなかった"],"answer":3,"vi":"Câu chuyện buồn cười quá nên tôi không thể nhịn cười.","explain":"ずにはいられない: hành động tự nhiên không kìm được (vì quá buồn cười). ずじまい là 'rốt cuộc không làm', ずにすんだ là 'may mà không phải', ずにおいた là 'cố ý không làm', đều trái với ので."},{"q":"{困|こま}っている{人|ひと}を{見|み}ると、{声|こえ}をかけ（　　）。","options":["ないことはない","ないではいられない","ないほうがいい","ないで{済|す}む"],"answer":1,"vi":"Hễ thấy người đang gặp khó khăn là tôi không thể không bắt chuyện hỏi han.","explain":"ないではいられない: cảm xúc tự nhiên thôi thúc hành động. ないで済む là 'khỏi phải', ないほうがいい là lời khuyên, không hợp."}],
  "25.3": [{"q":"{明日|あした}は{大事|だいじ}な{会議|かいぎ}があるので、{熱|ねつ}があっても{会社|かいしゃ}に{行|い}か（　　）。","options":["ないわけにはいかない","ないではいられない","ずじまいだ","ないことはない"],"answer":0,"vi":"Ngày mai có cuộc họp quan trọng nên dù sốt cũng không thể không đến công ty.","explain":"ないわけにはいかない: do hoàn cảnh/trách nhiệm nên buộc phải làm. ないではいられない là cảm xúc tự nhiên; ずじまい là 'rốt cuộc không làm'."},{"q":"{先輩|せんぱい}に{誘|さそ}われた{飲|の}み{会|かい}だから、{参加|さんか}し（　　）。","options":["ないでおく","ないではいられない","ないわけにはいかない","なくてもいい"],"answer":2,"vi":"Vì là buổi nhậu tiền bối mời nên tôi không thể không tham gia.","explain":"ないわけにはいかない: lẽ thường xã hội buộc phải làm (tiền bối mời). ないではいられない là cảm xúc tự nhiên; なくてもいい trái logic."}],
  "25.4": [{"q":"{台風|たいふう}が{近|ちか}づいているので、{明日|あした}の{試合|しあい}は{中止|ちゅうし}せ（　　）。","options":["ずにはいられない","ざるを{得|え}ない","ずじまいだ","ずに{済|す}む"],"answer":1,"vi":"Vì bão đang đến gần nên trận đấu ngày mai đành phải hủy.","explain":"ざるを得ない: không muốn nhưng hoàn cảnh buộc phải. ずにはいられない là cảm xúc tự nhiên, ずに済む là 'khỏi phải', trái nghĩa."},{"q":"{本当|ほんとう}は{行|い}きたくないが、{上司|じょうし}の{命令|めいれい}なので{出張|しゅっちょう}に{行|い}か（　　）。","options":["ずじまいだ","ずに{済|す}む","ずにはいられない","ざるを{得|え}ない"],"answer":3,"vi":"Thật ra tôi không muốn đi nhưng vì là lệnh của cấp trên nên đành phải đi công tác.","explain":"ざるを得ない: không muốn nhưng đành phải (行きたくないが). ずにはいられない là tự nhiên muốn làm, mâu thuẫn với 行きたくない."}],
  "26.0": [{"q":"{一度|いちど}でいいから、{世界一周|せかいいっしゅう}{旅行|りょこう}をしてみ（　　）。","options":["たものだ","るものか","たいものだ","たところだ"],"answer":2,"vi":"Chỉ một lần thôi cũng được, thật muốn thử đi du lịch vòng quanh thế giới.","explain":"たいものだ: bày tỏ mong muốn tha thiết trong lòng. たものだ là hồi tưởng, るものか là phủ định mạnh, たところだ là vừa mới làm."},{"q":"{早|はや}く{戦争|せんそう}のない{平和|へいわ}な{世界|せかい}になって（　　）。","options":["ほしいものだ","いるものだ","しまうものだ","おくものだ"],"answer":0,"vi":"Mong sao thế giới sớm trở nên hòa bình, không còn chiến tranh.","explain":"てほしいものだ: mong muốn người khác/sự việc như vậy. ているものだ/てしまうものだ/ておくものだ không diễn tả nguyện vọng."}],
  "26.1": [{"q":"{学生|がくせい}のころは、よく{友達|ともだち}と{朝|あさ}まで{語|かた}り{合|あ}った（　　）。","options":["ことだ","ばかりだ","ところだ","ものだ"],"answer":3,"vi":"Hồi còn là sinh viên, tôi thường hay trò chuyện với bạn bè đến tận sáng.","explain":"Vたものだ: hồi tưởng thói quen trong quá khứ (よく). たところだ là 'vừa mới', たばかりだ là 'vừa xong', không hợp với 学生のころ."},{"q":"もう{卒業|そつぎょう}して{十年|じゅうねん}か。{時間|じかん}が{経|た}つのは{本当|ほんとう}に{早|はや}い（　　）。","options":["はずだ","ものだ","わけだ","ところだ"],"answer":1,"vi":"Đã tốt nghiệp được mười năm rồi sao. Thời gian trôi thật là nhanh.","explain":"ものだ (cảm thán) nhấn mạnh cảm xúc, hay đi với 本当に. はずだ là suy đoán, わけだ là giải thích lý do, không hợp."}],
  "26.2": [{"q":"この{渋滞|じゅうたい}、なんとかして{早|はや}く{抜|ぬ}けられ（　　）。","options":["ないものか","ないわけか","ないことはない","ないことか"],"answer":0,"vi":"Cái vụ kẹt xe này, liệu có cách nào thoát ra sớm không đây.","explain":"なんとかして〜ないものか: mong muốn điều khó xảy ra. ないことはない là 'không phải là không thể', không diễn tả mong muốn."},{"q":"{何|なん}とかして{彼女|かのじょ}の{誤解|ごかい}を{解|と}くことはでき（　　）だろうか。","options":["ないわけ","ないこと","ないもの","ないはず"],"answer":2,"vi":"Liệu có cách nào giải tỏa được sự hiểu lầm của cô ấy không nhỉ.","explain":"できないものだろうか: tha thiết mong điều gì đó thực hiện được. ないことだろうか/ないわけだろうか/ないはずだろうか không mang nghĩa mong muốn."}],
  "26.3": [{"q":"{子供|こども}たちの{一生懸命|いっしょうけんめい}な{姿|すがた}には、{胸|むね}を{打|う}つ（　　）。","options":["ものか","ものがある","おそれがある","にすぎない"],"answer":1,"vi":"Dáng vẻ hết mình của bọn trẻ thật sự có điều gì đó làm xúc động lòng người.","explain":"ものがある: người nói cảm nhận thấy điều gì đó. おそれがある dùng cho việc xấu, ものか là phủ định, にすぎない hạ thấp."},{"q":"{八十歳|はちじゅっさい}でフルマラソンを{走|はし}るとは、{彼|かれ}の{体力|たいりょく}には{驚|おどろ}くべき（　　）。","options":["ところだった","はずがない","わけがない","ものがある"],"answer":3,"vi":"Chạy cả marathon ở tuổi tám mươi, thể lực của ông ấy thật có gì đó đáng kinh ngạc.","explain":"〜べきものがある: cảm tưởng mạnh của người nói. はずがない/わけがない phủ định, trái nghĩa; ところだった là 'suýt'."}],
  "26.4": [{"q":"{一人|ひとり}で{三人|さんにん}の{子供|こども}を{育|そだ}てたなんて、{本当|ほんとう}に{立派|りっぱ}な（　　）。","options":["ものか","わけだ","ことだ","はずだ"],"answer":2,"vi":"Một mình nuôi ba đứa con, thật là đáng nể.","explain":"Naなことだ: cảm thán chủ quan 'thật là…'. ものか phủ định, わけだ/はずだ là giải thích, suy đoán, không phải cảm thán."},{"q":"こんな{寒|さむ}い{朝|あさ}に{毎日|まいにち}ジョギングとは、ご{苦労|くろう}な（　　）。","options":["ことだ","ものか","ばかりだ","ところだ"],"answer":0,"vi":"Sáng lạnh thế này mà ngày nào cũng chạy bộ, thật là vất vả.","explain":"ご苦労なことだ: cảm thán 'thật là…'. ものか phủ định mạnh; ばかりだ/ところだ không đi với tính từ để cảm thán."}],
  "26.5": [{"q":"{合格|ごうかく}の{知|し}らせを{聞|き}いて、{両親|りょうしん}はどんなに{喜|よろこ}んだ（　　）。","options":["ものか","わけか","ばかりか","ことか"],"answer":3,"vi":"Nghe tin đỗ, bố mẹ tôi đã vui mừng biết bao.","explain":"どんなに〜ことか: nhấn mạnh mức độ 'biết bao'. ものか là phủ định mạnh, ばかりか là 'không chỉ', không hợp với どんなに."},{"q":"{一人暮|ひとりぐ}らしを{始|はじ}めて、{家族|かぞく}のありがたさを{何度|なんど}{感|かん}じた（　　）。","options":["はずだろう","ことだろう","ものだろう","わけだろう"],"answer":1,"vi":"Từ khi bắt đầu sống một mình, không biết bao nhiêu lần tôi đã cảm nhận được sự quý giá của gia đình.","explain":"何度〜ことだろう: cảm thán về mức độ, số lần nhiều. はずだろう/わけだろう là suy đoán, giải thích, không mang nghĩa cảm thán."}]
});
